#[derive(Debug, Default)]
pub struct RejectingHost;

impl VmHost for RejectingHost {
    fn invoke(&mut self, name: &str, _arguments: &[RuntimeValue]) -> Result<RuntimeValue, VmError> {
        Err(VmError::UnsupportedHostCall(name.to_owned()))
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum VmOutcome {
    Returned(RuntimeValue),
    Panicked(VmPanic),
}

#[derive(Debug, Clone, PartialEq)]
pub struct VmExecution {
    pub outcome: VmOutcome,
    pub statistics: VmStatistics,
    /// Present only when the opt-in runtime collector was requested.
    pub diagnostics: Option<DiagnosticTrace>,
}

pub fn execute(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
    host: &mut dyn VmHost,
) -> Result<VmExecution, VmError> {
    execute_with_limits(program, entry, host, VmLimits::default())
}

/// Executes a verified function with detached scalar arguments.
///
/// The ordinary entry point remains zero-argument because a Tondo program
/// starts at `main`.  Native-backend differential tooling also needs to invoke
/// a pure, lowered function directly; this boundary accepts only values that
/// can be transferred without borrowing the VM heap and rejects managed or
/// host-owned values rather than inventing a calling convention for them.
pub fn execute_with_arguments(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
    arguments: Vec<RuntimeValue>,
    host: &mut dyn VmHost,
) -> Result<VmExecution, VmError> {
    let arguments = arguments
        .into_iter()
        .map(initial_value)
        .collect::<Result<Vec<_>, _>>()?;
    execute_with_initial_values(
        program,
        entry,
        arguments,
        host,
        VmLimits::default(),
        ValueCopyStrategy::default(),
        None,
    )
}

pub fn execute_with_limits(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
    host: &mut dyn VmHost,
    limits: VmLimits,
) -> Result<VmExecution, VmError> {
    execute_with_limits_and_copy_strategy(
        program,
        entry,
        host,
        limits,
        ValueCopyStrategy::default(),
    )
}

/// Executes verified bytecode with an explicit physical value-copy strategy.
///
/// This entry point exists so the eager reference implementation and the COW
/// implementation can run the same black-box conformance corpus.
pub fn execute_with_limits_and_copy_strategy(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
    host: &mut dyn VmHost,
    limits: VmLimits,
    copy_strategy: ValueCopyStrategy,
) -> Result<VmExecution, VmError> {
    execute_with_limits_and_copy_strategy_and_diagnostics(
        program,
        entry,
        host,
        limits,
        copy_strategy,
        None,
    )
}

/// Executes verified bytecode with bounded runtime observations enabled.
///
/// Diagnostics are deliberately separate from the ordinary entry points so a
/// normal execution does not pay for event allocation or source-map metadata.
pub fn execute_with_diagnostics(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
    host: &mut dyn VmHost,
    config: DiagnosticConfig,
) -> Result<VmExecution, VmError> {
    execute_with_limits_and_copy_strategy_and_diagnostics(
        program,
        entry,
        host,
        VmLimits::default(),
        ValueCopyStrategy::default(),
        Some(config),
    )
}

/// Low-level diagnostic entry point used by the hosted runner and detector
/// tests. `None` is exactly the normal, uninstrumented VM path.
pub fn execute_with_limits_and_copy_strategy_and_diagnostics(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
    host: &mut dyn VmHost,
    limits: VmLimits,
    copy_strategy: ValueCopyStrategy,
    diagnostics: Option<DiagnosticConfig>,
) -> Result<VmExecution, VmError> {
    execute_with_initial_values(
        program,
        entry,
        Vec::new(),
        host,
        limits,
        copy_strategy,
        diagnostics,
    )
}

fn execute_with_initial_values(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
    arguments: Vec<Value>,
    host: &mut dyn VmHost,
    limits: VmLimits,
    copy_strategy: ValueCopyStrategy,
    diagnostics: Option<DiagnosticConfig>,
) -> Result<VmExecution, VmError> {
    validate_limits(limits)?;
    let diagnostics = diagnostics.map(DiagnosticSession::new).transpose()?;
    let trace = verify_bytecode_with_trace_metadata(
        program,
        BytecodeVerificationLimits {
            max_dataflow_steps: limits.max_verification_steps,
        },
    )?;
    validate_entry_contract(program, entry)?;
    if diagnostics.is_none() {
        Engine::new(program, host, limits, copy_strategy, trace).run(entry, arguments)
    } else {
        Engine::new_with_diagnostics(program, host, limits, copy_strategy, trace, diagnostics)
            .run(entry, arguments)
    }
}

fn initial_value(value: RuntimeValue) -> Result<Value, VmError> {
    match value {
        RuntimeValue::Unit => Ok(Value::Unit),
        RuntimeValue::Bool(value) => Ok(Value::Bool(value)),
        RuntimeValue::Integer(value) => Ok(Value::Integer(value)),
        RuntimeValue::Float(value) => Ok(Value::Float(value)),
        RuntimeValue::Byte(value) => Ok(Value::Byte(value)),
        RuntimeValue::Char(value) => Ok(Value::Char(value)),
        other => Err(VmError::InvalidEntry(format!(
            "initial argument is not a detached scalar: {other:?}"
        ))),
    }
}

fn validate_entry_contract(
    program: &BytecodeProgram,
    entry: BytecodeFunctionId,
) -> Result<(), VmError> {
    let function = program
        .function(entry)
        .ok_or_else(|| VmError::InvalidEntry(format!("unknown function {}", entry.index())))?;
    let callable = program.callable(function.callable).ok_or_else(|| {
        VmError::InvalidEntry("the selected function has no callable contract".into())
    })?;
    let signature = program.ty(callable.function_type).ok_or_else(|| {
        VmError::InvalidEntry("the selected callable has no function type".into())
    })?;
    let BytecodeTypeKind::Function(signature) = &signature.kind else {
        return Err(VmError::InvalidEntry(
            "the selected callable contract is not a function".into(),
        ));
    };
    if signature.is_unsafe {
        return Err(VmError::InvalidEntry(
            "the selected callable requires an unsafe execution context".into(),
        ));
    }
    Ok(())
}

fn validate_limits(limits: VmLimits) -> Result<(), VmError> {
    for (name, value) in [
        ("max_verification_steps", limits.max_verification_steps),
        ("max_steps", limits.max_steps),
        ("max_stack_depth", u64::from(limits.max_stack_depth)),
        ("max_heap_objects", u64::from(limits.max_heap_objects)),
        ("max_heap_bytes", limits.max_heap_bytes),
        (
            "initial_gc_threshold",
            u64::from(limits.initial_gc_threshold),
        ),
    ] {
        if value == 0 {
            return Err(VmError::InvalidLimits(name));
        }
    }
    Ok(())
}

fn run_blocking_job(
    program: &BytecodeProgram,
    trace: &BytecodeTraceMetadata,
    limits: VmLimits,
    copy_strategy: ValueCopyStrategy,
    job: BlockingJob,
    host: &mut BlockingWorkerHost,
) -> BlockingCompletion {
    let mut engine = Engine::new(program, host, limits, copy_strategy, trace.clone());
    let arguments = match engine.materialize_blocking_arguments(job.function, job.arguments) {
        Ok(arguments) => arguments,
        Err(error) => return BlockingCompletion::Failed(error),
    };
    match engine.run(job.function, arguments) {
        Ok(execution) => match execution.outcome {
            VmOutcome::Returned(value) => BlockingCompletion::Returned(value),
            VmOutcome::Panicked(panic) => BlockingCompletion::Panicked(panic),
        },
        Err(error) => BlockingCompletion::Failed(error),
    }
}

