    #[test]
    fn selectable_actor_send_waiter_wakes_only_after_capacity_opens() {
        let (program, types) = executor_program();
        let mut host = RejectingHost;
        let mut engine = executor_engine(&program, &mut host);
        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine.tasks.push(scheduler_task(TaskStatus::Waiting(
            TaskWait::ActorSelectSend { actor: 7 },
        )));
        engine.pools.insert(1, open_executor_pool(1, 1));
        engine.actors.insert(
            7,
            RuntimeActorState {
                pool: 1,
                state: Value::Integer(0),
                step: types.actor_handler,
                step_arguments: Vec::new(),
                capacity: 1,
                mailbox: VecDeque::from([Value::Integer(1)]),
                stopped: false,
                stopping: false,
                handler_task: None,
                terminal: None,
                send_waiters: VecDeque::from([1]),
            },
        );

        engine.wake_actor_send_waiter(7).unwrap();
        assert!(matches!(
            engine.tasks[1].status,
            TaskStatus::Waiting(TaskWait::ActorSelectSend { actor: 7 })
        ));
        assert_eq!(engine.actors[&7].send_waiters, VecDeque::from([1]));

        engine.actors.get_mut(&7).unwrap().mailbox.pop_front();
        engine.wake_actor_send_waiter(7).unwrap();
        assert!(matches!(engine.tasks[1].status, TaskStatus::Runnable));
        assert!(engine.actors[&7].send_waiters.is_empty());
        engine.current_task = 1;
        assert!(!engine.resume_current_task().unwrap());
        assert!(matches!(
            engine.tasks[1].status,
            TaskStatus::Complete(Some(TaskCompletion::Returned(Value::Unit)))
        ));
    }

    #[test]
    fn select_registration_covers_join_operation_and_unobserved_panic_resume() {
        let mut program = root_pressure_program();
        let int = BytecodeTypeId::new(5);
        let join = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Join[Int, Int]".into(),
            kind: BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Join,
                arguments: vec![int, int],
            },
        });
        program.functions.push(BytecodeFunction {
            callable: BytecodeCallableId::new(0),
            source: BytecodeSpan {
                file: 0,
                start: 0,
                end: 0,
            },
            types: Vec::new(),
            spans: vec![BytecodeSpan {
                file: 0,
                start: 0,
                end: 0,
            }],
            slots: Vec::new(),
            loans: Vec::new(),
            parameters: Vec::new(),
            return_slot: BytecodeSlotId::new(0),
            entry: BytecodeBlockId::new(0),
            unwind: BytecodeBlockId::new(0),
            blocks: Vec::new(),
        });

        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
            TaskCompletion::Returned(Value::Integer(7)),
        ))));
        engine.tasks[1].join_consumed = false;
        engine.frames.push({
            let mut frame = select_test_frame(RuntimeSelectRegion {
                capacity: 2,
                registered: 0,
                arms: Vec::new(),
            });
            frame.slots = vec![SlotState::Value(Value::Join(RuntimeJoin {
                task: 1,
                scope: super::TRANSFERRED_JOIN_SCOPE,
            }))];
            frame
        });
        assert!(engine.current_function(0).is_ok());
        let owner = BytecodePlace {
            slot: BytecodeSlotId::new(0),
            ty: join,
            projections: Vec::new(),
            source_loan: None,
        };
        engine
            .register_select_arm(
                0,
                0,
                &BytecodeSelectRegistration::Join(owner),
                crate::bytecode::BytecodeSpanId::new(0),
            )
            .unwrap();
        let constant = |value: &str| BytecodeOperand {
            ty: int,
            kind: BytecodeOperandKind::Constant(BytecodeConstant::Integer(value.into())),
        };
        let operation = BytecodeOperation {
            ty: int,
            kind: BytecodeOperationKind::CheckedBinary {
                operator: BytecodeBinaryOperator::Add,
                left: constant("2"),
                right: constant("3"),
            },
        };
        engine
            .register_select_arm(
                0,
                1,
                &BytecodeSelectRegistration::Call(operation),
                crate::bytecode::BytecodeSpanId::new(0),
            )
            .unwrap();
        assert_eq!(engine.frames[0].select.as_ref().unwrap().registered, 2);
        assert_eq!(engine.tasks.len(), 3);
        assert!(matches!(
            engine.tasks[2].status,
            TaskStatus::Complete(Some(TaskCompletion::Returned(Value::Integer(5))))
        ));

        let mut panic_host = RejectingHost;
        let mut panic_engine = Engine::new(
            &program,
            &mut panic_host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            derive_trace_metadata(&program).unwrap(),
        );
        panic_engine.tasks.push(scheduler_task(TaskStatus::Running));
        let child_panic = VmPanic {
            code: PanicCode::ExplicitPanic,
            message: "child".into(),
            span: BytecodeSpan {
                file: 0,
                start: 0,
                end: 0,
            },
            stack: vec![VmStackFrame {
                function: "child".into(),
                span: BytecodeSpan {
                    file: 0,
                    start: 0,
                    end: 0,
                },
            }],
            suppressed: Vec::new(),
        };
        panic_engine
            .tasks
            .push(scheduler_task(TaskStatus::Complete(Some(
                TaskCompletion::Panicked(child_panic),
            ))));
        panic_engine.task_scopes.push(Some(RuntimeTaskScope {
            source: BytecodeScopeId::new(0),
            owner: 0,
            children: vec![1],
            closed: false,
        }));
        let mut frame = select_test_frame(RuntimeSelectRegion {
            capacity: 1,
            registered: 0,
            arms: Vec::new(),
        });
        frame.task_scopes.push(0);
        panic_engine.frames.push(frame);
        panic_engine.tasks[0].resume = Some(TaskWait::Select {
            unwind: BytecodeBlockId::new(11),
        });
        assert!(panic_engine.resume_current_task().unwrap());
        assert!(matches!(
            panic_engine.pending_unwind,
            Some(RuntimeUnwind::Cancelled)
        ));
    }

    #[test]
    fn async_collect_owner_rejects_uninitialized_state_at_each_boundary() {
        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        );

        assert!(
            engine
                .spawn_async_iterator_collect(
                    Value::Unit,
                    Value::Unit,
                    Value::Integer(1),
                    BytecodeTypeId::new(5),
                    0,
                )
                .is_err()
        );

        engine.tasks.push(scheduler_task(TaskStatus::Runnable));
        assert!(engine.start_async_collect().is_err());
        assert!(engine.start_async_collect_next().is_err());
        assert!(engine.finish_async_collect_next(Value::Integer(0)).is_err());
        assert!(engine.complete_async_collect_success().is_err());
    }

    #[test]
    fn completed_and_cancelled_tasks_register_in_their_parent_scope() {
        let mut program = root_pressure_program();
        let waiter_ty = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Waiter".into(),
            kind: BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Waiter,
                arguments: vec![BytecodeTypeId::new(5), BytecodeTypeId::new(0)],
            },
        });
        let completer_ty = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Completer".into(),
            kind: BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Completer,
                arguments: vec![BytecodeTypeId::new(5), BytecodeTypeId::new(0)],
            },
        });
        let pair_ty = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "(Waiter, Completer)".into(),
            kind: BytecodeTypeKind::Tuple(vec![waiter_ty, completer_ty]),
        });
        let result_ty = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Int ! Int".into(),
            kind: BytecodeTypeKind::Result {
                success: BytecodeTypeId::new(5),
                error: BytecodeTypeId::new(5),
            },
        });
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        engine.task_scopes.push(Some(RuntimeTaskScope {
            source: BytecodeScopeId::new(0),
            owner: 0,
            children: Vec::new(),
            closed: false,
        }));

        let OperationResult::Value(Value::Heap(_)) = engine.new_oneshot(pair_ty).unwrap() else {
            panic!("new one-shot did not return its pair")
        };
        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine
            .park_oneshot(
                1,
                TaskWait::OneShotTask {
                    id: 1,
                    outcome: result_ty,
                },
            )
            .unwrap();
        assert!(
            engine
                .park_oneshot(
                    99,
                    TaskWait::OneShotTask {
                        id: 99,
                        outcome: result_ty,
                    },
                )
                .is_err()
        );
        assert!(
            !engine
                .complete_oneshot(1, OneShotCompletion::Ok(Value::Integer(7)))
                .unwrap()
        );
        assert!(
            engine
                .complete_oneshot(1, OneShotCompletion::Cancelled)
                .unwrap()
        );
        assert!(
            engine
                .oneshot_result(result_ty, Ok(Value::Integer(1)))
                .is_ok()
        );
        assert!(engine.oneshot_result(result_ty, Err(Value::Unit)).is_ok());
        assert!(
            engine
                .oneshot_result(BytecodeTypeId::new(5), Ok(Value::Unit))
                .is_err()
        );
        assert!(
            engine
                .oneshot_result(BytecodeTypeId::new(999), Ok(Value::Unit))
                .is_err()
        );

        engine.oneshots.insert(2, OneShotState::default());
        let pending = engine.spawn_oneshot_task(2, result_ty, 0).unwrap();
        assert!(matches!(
            engine.tasks[pending].status,
            TaskStatus::Waiting(_)
        ));
        assert!(engine.spawn_oneshot_task(2, result_ty, 99).is_err());
        engine
            .complete_oneshot(2, OneShotCompletion::Cancelled)
            .unwrap();
        let cancelled_child = engine.spawn_oneshot_task(2, result_ty, 0).unwrap();
        assert!(matches!(
            engine.tasks[cancelled_child].status,
            TaskStatus::Complete(Some(TaskCompletion::Cancelled))
        ));
        engine.oneshots.insert(
            3,
            OneShotState {
                completion: Some(OneShotCompletion::Ok(Value::Integer(1))),
                ..OneShotState::default()
            },
        );
        assert!(engine.spawn_oneshot_task(3, result_ty, 0).is_err());
        assert!(engine.spawn_oneshot_task(999, result_ty, 0).is_err());
        assert!(
            engine
                .complete_oneshot(999, OneShotCompletion::Cancelled)
                .is_err()
        );

        let waiter = |name: &str, parameters: Vec<BytecodeParameter>| BytecodeCallable {
            name: name.into(),
            generic_arity: 0,
            parameters,
            outcome: result_ty,
            function_type: result_ty,
            implementation: None,
            closure: None,
        };
        let receiver = BytecodeParameter {
            mode: BytecodeParameterMode::Value,
            ty: waiter_ty,
            variadic_element: None,
            receiver: true,
        };
        assert!(
            engine
                .prepare_oneshot_method(&waiter("std.async.Waiter.wait", Vec::new()), &[])
                .is_err()
        );
        assert!(
            engine
                .prepare_oneshot_method(&waiter("std.async.Waiter.wait", vec![receiver]), &[])
                .is_err()
        );
        let waiter_value = Value::Host(RuntimeValue::Host {
            kind: RuntimeHostValueKind::Waiter,
            id: 6,
        });
        engine.oneshots.insert(6, OneShotState::default());
        assert!(matches!(
            engine
                .prepare_oneshot_method(
                    &waiter("std.async.Waiter.wait", vec![receiver]),
                    std::slice::from_ref(&waiter_value),
                )
                .unwrap(),
            Some(OperationResult::OneShotWait { id: 6, .. })
        ));
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter("std.async.Waiter.wait", vec![receiver]),
                    &[waiter_value],
                )
                .is_err()
        );
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter("std.async.Waiter.wait", vec![receiver]),
                    &[Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::Waiter,
                        id: 99,
                    })],
                )
                .is_err()
        );

        let completer_receiver = BytecodeParameter {
            ty: completer_ty,
            ..receiver
        };
        assert!(
            engine
                .prepare_oneshot_method(&waiter("std.async.Completer.complete", Vec::new()), &[],)
                .is_err()
        );
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter("std.async.Completer.complete", vec![completer_receiver]),
                    &[],
                )
                .is_err()
        );
        engine.oneshots.insert(4, OneShotState::default());
        let completer_value = Value::Host(RuntimeValue::Host {
            kind: RuntimeHostValueKind::Completer,
            id: 4,
        });
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter("std.async.Completer.complete", vec![completer_receiver],),
                    std::slice::from_ref(&completer_value),
                )
                .is_err()
        );
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter(
                        "std.async.Completer.complete",
                        vec![completer_receiver, receiver],
                    ),
                    &[completer_value.clone(), Value::Integer(9)],
                )
                .unwrap()
                .is_some()
        );
        engine.oneshots.insert(7, OneShotState::default());
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter(
                        "std.async.Completer.fail",
                        vec![completer_receiver, receiver],
                    ),
                    &[Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::Completer,
                        id: 7,
                    })],
                )
                .is_err()
        );
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter(
                        "std.async.Completer.complete",
                        vec![completer_receiver, receiver],
                    ),
                    &[completer_value.clone(), Value::Integer(9)],
                )
                .unwrap()
                .is_some()
        );
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter(
                        "std.async.Completer.fail",
                        vec![completer_receiver, receiver],
                    ),
                    &[completer_value.clone(), Value::Integer(0)],
                )
                .unwrap()
                .is_some()
        );
        assert!(
            engine
                .prepare_oneshot_method(
                    &waiter("std.async.Completer.cancel", vec![completer_receiver]),
                    &[completer_value],
                )
                .unwrap()
                .is_some()
        );

        let completed = engine.spawn_completed_task(Value::Integer(42), 0).unwrap();
        let cancelled = engine.spawn_cancelled_task_with_scope(Some(0)).unwrap();
        assert!(engine.spawn_completed_task(Value::Unit, 99).is_err());
        assert!(engine.spawn_cancelled_task_with_scope(Some(99)).is_err());

        assert!(matches!(
            engine.tasks[completed].status,
            TaskStatus::Complete(Some(TaskCompletion::Returned(Value::Integer(42))))
        ));
        assert!(matches!(
            engine.tasks[cancelled].status,
            TaskStatus::Complete(Some(TaskCompletion::Cancelled))
        ));
        let children = &engine.task_scopes[0].as_ref().unwrap().children;
        assert!(children.contains(&completed));
        assert!(children.contains(&cancelled));
    }

    #[test]
    fn entry_and_limit_contracts_reject_each_invalid_boundary() {
        let mut program = root_pressure_program();
        let int = BytecodeTypeId::new(5);
        let function_type = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "fn main()".into(),
            kind: BytecodeTypeKind::Function(BytecodeFunctionType {
                is_async: false,
                is_selectable: false,
                is_unsafe: false,
                parameters: Vec::new(),
                variadic: None,
                outcome: int,
            }),
        });
        program.callables.push(BytecodeCallable {
            name: "main".into(),
            generic_arity: 0,
            parameters: Vec::new(),
            outcome: int,
            function_type,
            implementation: Some(BytecodeFunctionId::new(0)),
            closure: None,
        });
        program.functions.push(BytecodeFunction {
            callable: BytecodeCallableId::new(0),
            source: BytecodeSpan {
                file: 0,
                start: 0,
                end: 0,
            },
            types: Vec::new(),
            spans: vec![BytecodeSpan {
                file: 0,
                start: 0,
                end: 0,
            }],
            slots: Vec::new(),
            loans: Vec::new(),
            parameters: Vec::new(),
            return_slot: BytecodeSlotId::new(0),
            entry: BytecodeBlockId::new(0),
            unwind: BytecodeBlockId::new(0),
            blocks: Vec::new(),
        });
        let entry = BytecodeFunctionId::new(0);
        super::validate_entry_contract(&program, entry).unwrap();

        let error =
            super::validate_entry_contract(&program, BytecodeFunctionId::new(99)).unwrap_err();
        assert!(
            matches!(error, VmError::InvalidEntry(message) if message.contains("unknown function"))
        );

        let mut missing_callable = program.clone();
        missing_callable.functions[0].callable = BytecodeCallableId::new(99);
        let error = super::validate_entry_contract(&missing_callable, entry).unwrap_err();
        assert!(matches!(error, VmError::InvalidEntry(message) if message.contains("no callable")));

        let mut missing_signature = program.clone();
        missing_signature.callables[0].function_type = BytecodeTypeId::new(99);
        let error = super::validate_entry_contract(&missing_signature, entry).unwrap_err();
        assert!(
            matches!(error, VmError::InvalidEntry(message) if message.contains("no function type"))
        );

        let mut non_function = program.clone();
        non_function.callables[0].function_type = int;
        let error = super::validate_entry_contract(&non_function, entry).unwrap_err();
        assert!(
            matches!(error, VmError::InvalidEntry(message) if message.contains("not a function"))
        );

        let mut unsafe_entry = program.clone();
        let BytecodeTypeKind::Function(signature) =
            &mut unsafe_entry.types[function_type.index() as usize].kind
        else {
            unreachable!()
        };
        signature.is_unsafe = true;
        let error = super::validate_entry_contract(&unsafe_entry, entry).unwrap_err();
        assert!(matches!(error, VmError::InvalidEntry(message) if message.contains("unsafe")));

        for (name, limits) in [
            (
                "max_verification_steps",
                VmLimits {
                    max_verification_steps: 0,
                    ..VmLimits::default()
                },
            ),
            (
                "max_steps",
                VmLimits {
                    max_steps: 0,
                    ..VmLimits::default()
                },
            ),
            (
                "max_stack_depth",
                VmLimits {
                    max_stack_depth: 0,
                    ..VmLimits::default()
                },
            ),
            (
                "max_heap_objects",
                VmLimits {
                    max_heap_objects: 0,
                    ..VmLimits::default()
                },
            ),
            (
                "max_heap_bytes",
                VmLimits {
                    max_heap_bytes: 0,
                    ..VmLimits::default()
                },
            ),
            (
                "initial_gc_threshold",
                VmLimits {
                    initial_gc_threshold: 0,
                    ..VmLimits::default()
                },
            ),
        ] {
            let error = super::validate_limits(limits).unwrap_err();
            assert!(matches!(error, VmError::InvalidLimits(candidate) if candidate == name));
        }
    }

    #[test]
    fn deferred_operation_and_cleanup_roots_cover_all_runtime_shapes() {
        let ty = BytecodeTypeId::new(5);
        let place = BytecodePlace {
            slot: BytecodeSlotId::new(0),
            ty,
            projections: Vec::new(),
            source_loan: None,
        };
        let captured = Value::Integer(7);
        let mut roots = Vec::new();
        DeferredValue::Captured(captured.clone()).roots(&mut roots);
        DeferredValue::Guard.roots(&mut roots);
        assert_eq!(roots, vec![captured.clone()]);

        let assertion = DeferredOperation::Assert {
            condition: DeferredValue::Captured(captured.clone()),
            condition_repr: "value".into(),
            message_parts: vec![(DeferredValue::Guard, false)],
        };
        assertion.roots(&mut roots);
        assert_eq!(roots, vec![captured.clone(), captured.clone()]);

        let host_call = DeferredOperation::BootstrapHostCall {
            function: crate::bytecode::BytecodeBootstrapHostFunction::ConsolePrint,
            arguments: vec![
                DeferredValue::Captured(captured.clone()),
                DeferredValue::Guard,
            ],
        };
        host_call.roots(&mut roots);
        assert_eq!(roots, vec![captured.clone(), captured.clone(), captured]);

        let scope = BytecodeScopeId::new(3);
        let mut explicit = RuntimeCleanup::Explicit(RuntimeDefer {
            scope,
            span: BytecodeSpan {
                file: 0,
                start: 0,
                end: 0,
            },
            operation: assertion,
            guard: Some(place.clone()),
            async_cleanup: false,
        });
        assert_eq!(explicit.scope(), scope);
        assert_eq!(explicit.guard(), Some(&place));
        explicit.guard_mut().unwrap().slot = BytecodeSlotId::new(1);
        explicit.roots(&mut roots);

        let mut fallback = RuntimeCleanup::Fallback(RuntimeFallback {
            scope,
            owner: place,
        });
        assert_eq!(fallback.scope(), scope);
        assert!(fallback.guard().is_some());
        fallback.guard_mut().unwrap().slot = BytecodeSlotId::new(2);
        let before = roots.len();
        fallback.roots(&mut roots);
        assert_eq!(roots.len(), before);
    }

    #[test]
    fn terminal_fallback_dismantles_every_managed_shape_without_retaining_children() {
        let program = terminal_fallback_program();

        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(4),
                HeapObject::Tuple(vec![None, None]),
            ),
            HeapObject::Tuple(vec![None, None])
        );
        assert_eq!(
            execute_fallback_object(&program, BytecodeTypeId::new(9), HeapObject::OptionNone,),
            HeapObject::OptionNone
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(9),
                HeapObject::OptionSome(Some(Value::Unit)),
            ),
            HeapObject::OptionSome(None)
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(10),
                HeapObject::ResultOk(Some(Value::Unit)),
            ),
            HeapObject::ResultOk(None)
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(10),
                HeapObject::ResultErr(None),
            ),
            HeapObject::ResultErr(None)
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(11),
                HeapObject::Union {
                    member: BytecodeTypeId::new(0),
                    value: Some(Value::Unit),
                },
            ),
            HeapObject::Union {
                member: BytecodeTypeId::new(0),
                value: None,
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(1),
                HeapObject::Array(vec![Some(Value::Unit)].into()),
            ),
            HeapObject::Array(vec![None].into())
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(8),
                HeapObject::Set(vec![Some(Value::Unit)].into()),
            ),
            HeapObject::Set(vec![None].into())
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(2),
                HeapObject::Map(vec![(Some(Value::Unit), None)].into()),
            ),
            HeapObject::Map(vec![(None, None)].into())
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(3),
                HeapObject::Range {
                    kind: BytecodeRangeKind::Inclusive,
                    start: Some(Value::Unit),
                    end: Some(Value::Unit),
                },
            ),
            HeapObject::Range {
                kind: BytecodeRangeKind::Inclusive,
                start: None,
                end: None,
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(13),
                HeapObject::Newtype {
                    nominal: BytecodeNominalId::new(0),
                    value: Some(Value::Unit),
                },
            ),
            HeapObject::Newtype {
                nominal: BytecodeNominalId::new(0),
                value: None,
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(14),
                HeapObject::Record {
                    nominal: BytecodeNominalId::new(1),
                    fields: vec![(0, Some(Value::Unit)), (1, None)],
                },
            ),
            HeapObject::Record {
                nominal: BytecodeNominalId::new(1),
                fields: vec![(0, None), (1, None)],
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(15),
                HeapObject::Variant {
                    variant: 0,
                    payload: AggregatePayload::Unit,
                },
            ),
            HeapObject::Variant {
                variant: 0,
                payload: AggregatePayload::Unit,
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(15),
                HeapObject::Variant {
                    variant: 1,
                    payload: AggregatePayload::Tuple(vec![Some(Value::Unit)]),
                },
            ),
            HeapObject::Variant {
                variant: 1,
                payload: AggregatePayload::Tuple(vec![None]),
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(15),
                HeapObject::Variant {
                    variant: 2,
                    payload: AggregatePayload::Record(vec![(0, None)]),
                },
            ),
            HeapObject::Variant {
                variant: 2,
                payload: AggregatePayload::Record(vec![(0, None)]),
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(16),
                HeapObject::Closure {
                    callable: BytecodeCallableId::new(0),
                    captures: vec![Some(Value::Unit), None],
                },
            ),
            HeapObject::Closure {
                callable: BytecodeCallableId::new(0),
                captures: vec![None, None],
            }
        );
        assert_eq!(
            execute_fallback_object(
                &program,
                BytecodeTypeId::new(7),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: None,
                    next: 3,
                    adapter: None,
                },
            ),
            HeapObject::Iterator {
                mode: BytecodeCursorMode::Own,
                source: None,
                next: 3,
                adapter: None,
            }
        );

        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        );
        let fallback = install_fallback_frame(&mut engine, BytecodeTypeId::new(17), Value::Unit);
        engine.execute_terminal_fallback(0, fallback).unwrap();
    }

    #[test]
    fn terminal_fallback_rejects_every_incompatible_runtime_shape() {
        let program = terminal_fallback_program();

        assert_fallback_error(
            &program,
            BytecodeTypeId::new(999),
            Value::Unit,
            "unknown type",
        );
        assert_fallback_error(
            &program,
            BytecodeTypeId::new(12),
            Value::Unit,
            "cannot resolve a generic nominal component",
        );
        for (ty, expected) in [
            (4, "tuple fallback found a non-managed value"),
            (9, "Option fallback found a non-managed value"),
            (10, "Result fallback found a non-managed value"),
            (11, "union fallback found a non-managed value"),
            (1, "collection fallback found a non-managed value"),
            (8, "collection fallback found a non-managed value"),
            (2, "Map fallback found a non-managed value"),
            (3, "Range fallback found a non-managed value"),
            (13, "nominal fallback found a non-managed value"),
            (16, "closure fallback found a non-managed value"),
            (7, "cursor fallback found a non-managed value"),
        ] {
            assert_fallback_error(&program, BytecodeTypeId::new(ty), Value::Unit, expected);
        }
        assert_fallback_error(
            &program,
            BytecodeTypeId::new(18),
            Value::Unit,
            "ProcessHandle fallback found a non-host value",
        );
        assert_fallback_error(
            &program,
            BytecodeTypeId::new(20),
            Value::Unit,
            "Join fallback found no task handle",
        );

        for (ty, expected) in [
            (4, "tuple fallback found a different heap object"),
            (9, "Option fallback found a different heap object"),
            (10, "Result fallback found a different heap object"),
            (11, "union fallback found a different heap object"),
            (1, "collection fallback found a different heap object"),
            (8, "collection fallback found a different heap object"),
            (2, "Map fallback found a different heap object"),
            (3, "Range fallback found a different heap object"),
            (13, "nominal fallback found a different heap object"),
            (16, "closure fallback found a different heap object"),
            (7, "cursor fallback found a different heap object"),
        ] {
            assert_fallback_heap_error(
                &program,
                BytecodeTypeId::new(ty),
                HeapObject::String("wrong".into()),
                expected,
            );
        }
        assert_fallback_heap_error(
            &program,
            BytecodeTypeId::new(4),
            HeapObject::Tuple(vec![None]),
            "tuple fallback found the wrong arity",
        );
        assert_fallback_heap_error(
            &program,
            BytecodeTypeId::new(14),
            HeapObject::Record {
                nominal: BytecodeNominalId::new(1),
                fields: vec![(999, None)],
            },
            "record fallback found an unknown field",
        );
        assert_fallback_heap_error(
            &program,
            BytecodeTypeId::new(15),
            HeapObject::Variant {
                variant: 999,
                payload: AggregatePayload::Unit,
            },
            "enum fallback found an unknown variant",
        );
        assert_fallback_heap_error(
            &program,
            BytecodeTypeId::new(15),
            HeapObject::Variant {
                variant: 1,
                payload: AggregatePayload::Unit,
            },
            "enum fallback found the wrong payload shape",
        );
        assert_fallback_heap_error(
            &program,
            BytecodeTypeId::new(16),
            HeapObject::Closure {
                callable: BytecodeCallableId::new(0),
                captures: vec![None],
            },
            "closure fallback found the wrong capture arity",
        );
        assert_fallback_heap_error(
            &program,
            BytecodeTypeId::new(7),
            HeapObject::Iterator {
                mode: BytecodeCursorMode::Ref,
                source: None,
                next: 0,
                adapter: None,
            },
            "cursor fallback found a ref iterator",
        );
    }

    #[test]
    fn terminal_process_fallback_invokes_the_host_cleanup_boundary() {
        #[derive(Default)]
        struct CleanupHost {
            cleaned: Vec<RuntimeValue>,
        }

        impl VmHost for CleanupHost {
            fn invoke(
                &mut self,
                name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<RuntimeValue, VmError> {
                Err(VmError::UnsupportedHostCall(name.into()))
            }

            fn cleanup(&mut self, value: &RuntimeValue) -> Result<(), VmError> {
                self.cleaned.push(value.clone());
                Ok(())
            }
        }

        let program = terminal_fallback_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = CleanupHost::default();
        {
            let mut engine = Engine::new(
                &program,
                &mut host,
                pressure_limits(),
                ValueCopyStrategy::default(),
                trace,
            );
            let fallback = install_fallback_frame(
                &mut engine,
                BytecodeTypeId::new(18),
                Value::Host(RuntimeValue::String("process".into())),
            );
            engine.execute_terminal_fallback(0, fallback).unwrap();
        }
        assert!(matches!(
            host.invoke("unsupported", &[]),
            Err(VmError::UnsupportedHostCall(name)) if name == "unsupported"
        ));
        assert_eq!(host.cleaned, [RuntimeValue::String("process".into())]);
    }

    #[test]
    fn default_host_and_closed_runtime_helpers_have_explicit_boundaries() {
        #[derive(Default)]
        struct MinimalHost;

        impl VmHost for MinimalHost {
            fn invoke(
                &mut self,
                name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<RuntimeValue, VmError> {
                Err(VmError::UnsupportedHostCall(name.into()))
            }
        }

        let mut host = MinimalHost;
        assert!(matches!(
            host.invoke("unsupported", &[]),
            Err(VmError::UnsupportedHostCall(name)) if name == "unsupported"
        ));
        assert!(matches!(
            host.start_async("work", &[]),
            Err(VmError::UnsupportedHostCall(name)) if name == "work"
        ));
        assert_eq!(host.poll_async(7).unwrap(), None);
        assert!(matches!(host.wait_async(&[]), Err(VmError::Invariant(_))));
        assert!(matches!(
            host.wait_async(&[7]),
            Err(VmError::UnsupportedHostCall(name)) if name == "async host call #7"
        ));
        host.cancel_async(7).unwrap();
        host.cleanup(&RuntimeValue::Unit).unwrap();
        assert!(matches!(
            host.begin_virtual_time(),
            Err(VmError::UnsupportedHostCall(name)) if name == "std.testing.withVirtualTime"
        ));
        assert!(matches!(
            host.finish_virtual_time(&RuntimeValue::Unit),
            Err(VmError::UnsupportedHostCall(name)) if name == "std.testing.withVirtualTime"
        ));
        assert!(!host.is_virtual_quiescence_call(7));
        assert!(matches!(
            host.begin_test_node(VmTestNodeKind::Leaf, "unit::leaf"),
            Err(VmError::UnsupportedHostCall(name)) if name == "test node `unit::leaf`"
        ));
        assert!(matches!(
            host.finish_test_node(
                VmTestNodeKind::Suite,
                "unit::suite",
                VmTestNodeOutcome::Passed,
            ),
            Err(VmError::UnsupportedHostCall(name)) if name == "test node `unit::suite`"
        ));
        assert!(matches!(
            host.begin_test_suite_cleanup(),
            Err(VmError::UnsupportedHostCall(name)) if name == "test suite cleanup"
        ));

        let mut rejecting = RejectingHost;
        assert!(matches!(
            rejecting.invoke("missing", &[]),
            Err(VmError::UnsupportedHostCall(name)) if name == "missing"
        ));

        for (constructor, expected) in [
            (
                BytecodeIntrinsicType::Command,
                RuntimeHostValueKind::Command,
            ),
            (
                BytecodeIntrinsicType::Pipeline,
                RuntimeHostValueKind::Pipeline,
            ),
            (BytecodeIntrinsicType::Bytes, RuntimeHostValueKind::Bytes),
            (
                BytecodeIntrinsicType::BytesBuilder,
                RuntimeHostValueKind::BytesBuilder,
            ),
            (
                BytecodeIntrinsicType::BytesError,
                RuntimeHostValueKind::BytesError,
            ),
            (
                BytecodeIntrinsicType::ExitStatus,
                RuntimeHostValueKind::ExitStatus,
            ),
            (
                BytecodeIntrinsicType::ProcessOutput,
                RuntimeHostValueKind::ProcessOutput,
            ),
            (
                BytecodeIntrinsicType::ProcessHandle,
                RuntimeHostValueKind::ProcessHandle,
            ),
            (
                BytecodeIntrinsicType::ProcessError,
                RuntimeHostValueKind::ProcessError,
            ),
            (
                BytecodeIntrinsicType::ProcessExitError,
                RuntimeHostValueKind::ProcessExitError,
            ),
            (
                BytecodeIntrinsicType::Utf8Error,
                RuntimeHostValueKind::Utf8Error,
            ),
            (
                BytecodeIntrinsicType::Instant,
                RuntimeHostValueKind::Instant,
            ),
            (BytecodeIntrinsicType::Timer, RuntimeHostValueKind::Timer),
            (
                BytecodeIntrinsicType::DurationError,
                RuntimeHostValueKind::DurationError,
            ),
            (
                BytecodeIntrinsicType::ClockError,
                RuntimeHostValueKind::ClockError,
            ),
            (
                BytecodeIntrinsicType::EnvSnapshot,
                RuntimeHostValueKind::EnvSnapshot,
            ),
            (
                BytecodeIntrinsicType::EnvName,
                RuntimeHostValueKind::EnvName,
            ),
            (
                BytecodeIntrinsicType::EnvValue,
                RuntimeHostValueKind::EnvValue,
            ),
            (
                BytecodeIntrinsicType::EnvError,
                RuntimeHostValueKind::EnvError,
            ),
        ] {
            assert_eq!(runtime_host_kind(constructor), Some(expected));
        }
        for constructor in [
            BytecodeIntrinsicType::Array,
            BytecodeIntrinsicType::Map,
            BytecodeIntrinsicType::Set,
            BytecodeIntrinsicType::Range,
            BytecodeIntrinsicType::Ref,
            BytecodeIntrinsicType::Pointer,
            BytecodeIntrinsicType::Join,
            BytecodeIntrinsicType::Duration,
            BytecodeIntrinsicType::NumericConversionError,
        ] {
            assert_eq!(runtime_host_kind(constructor), None);
        }

        assert_eq!(next_unicode_scalar(0x41), Some(0x42));
        assert_eq!(next_unicode_scalar(0xd7ff), Some(0xe000));
        assert_eq!(next_unicode_scalar(0x10ffff), None);
        assert_eq!(next_unicode_scalar(u32::MAX), None);
        assert!(collection_length_fits_int(0));
        assert!(!collection_length_fits_int(usize::MAX));

        let failure = PlaceFailure::from(VmError::invariant("closed"));
        assert!(matches!(
            failure,
            PlaceFailure::Vm(VmError::Invariant(message)) if message == "closed"
        ));
    }

    #[test]
    fn detached_scalar_entry_values_cover_the_closed_conversion_boundary() {
        for (input, expected) in [
            (RuntimeValue::Unit, Value::Unit),
            (RuntimeValue::Bool(true), Value::Bool(true)),
            (RuntimeValue::Integer(-7), Value::Integer(-7)),
            (RuntimeValue::Float(2.5), Value::Float(2.5)),
            (RuntimeValue::Byte(0xfe), Value::Byte(0xfe)),
            (RuntimeValue::Char('λ'), Value::Char('λ')),
        ] {
            assert_eq!(initial_value(input).unwrap(), expected);
        }

        let error = initial_value(RuntimeValue::String("managed".into())).unwrap_err();
        assert!(matches!(
            error,
            VmError::InvalidEntry(message) if message.contains("detached scalar")
        ));
    }

    #[test]
    fn format_builder_host_boundaries_are_materialized_atomically() {
        #[derive(Clone, Copy)]
        enum Mode {
            Success,
            InvalidBuilder,
            InvalidAppend,
            AppendError,
            InvalidFinish,
        }

        struct FormatHost {
            mode: Mode,
        }

        impl VmHost for FormatHost {
            fn invoke(
                &mut self,
                name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<RuntimeValue, VmError> {
                match (name, self.mode) {
                    ("std.format.Builder.new", Mode::InvalidBuilder) => {
                        Ok(RuntimeValue::String("wrong".into()))
                    }
                    ("std.format.Builder.new", _) => Ok(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::FormatBuilder,
                        id: 7,
                    }),
                    ("std.format.Builder.append", Mode::InvalidAppend) => Ok(RuntimeValue::Unit),
                    ("std.format.Builder.append", Mode::AppendError) => {
                        Ok(RuntimeValue::ResultErr(Box::new(RuntimeValue::Host {
                            kind: RuntimeHostValueKind::FormatError,
                            id: 8,
                        })))
                    }
                    ("std.format.Builder.append", _) => {
                        Ok(RuntimeValue::ResultOk(Box::new(RuntimeValue::Unit)))
                    }
                    ("std.format.Builder.finish", Mode::InvalidFinish) => Ok(RuntimeValue::Unit),
                    ("std.format.Builder.finish", _) => Ok(RuntimeValue::String("joined".into())),
                    _ => Err(VmError::UnsupportedHostCall(name.into())),
                }
            }
        }

        let mut program = root_pressure_program();
        let format_error = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "FormatError".into(),
            kind: BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::FormatError,
                arguments: Vec::new(),
            },
        });
        let result = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "String ! FormatError".into(),
            kind: BytecodeTypeKind::Result {
                success: BytecodeTypeId::new(0),
                error: format_error,
            },
        });
        let trace = derive_trace_metadata(&program).unwrap();

        for (mode, result_ty, expected_error) in [
            (Mode::Success, BytecodeTypeId::new(0), None),
            (
                Mode::InvalidBuilder,
                BytecodeTypeId::new(0),
                Some("non-builder"),
            ),
            (
                Mode::InvalidAppend,
                BytecodeTypeId::new(0),
                Some("invalid result"),
            ),
            (Mode::AppendError, result, None),
            (
                Mode::InvalidFinish,
                BytecodeTypeId::new(0),
                Some("bootstrap host result"),
            ),
        ] {
            let mut host = FormatHost { mode };
            let mut engine = Engine::new(
                &program,
                &mut host,
                pressure_limits(),
                ValueCopyStrategy::default(),
                trace.clone(),
            );
            let outcome = engine.format_text_result(result_ty, ["a".to_owned(), "b".to_owned()]);
            if let Some(expected_error) = expected_error {
                assert!(
                    matches!(&outcome, Err(VmError::Host(message)) if message.contains(expected_error))
                        || matches!(&outcome, Err(VmError::Invariant(message)) if message.contains(expected_error)),
                    "unexpected format boundary result: {outcome:?}"
                );
            } else {
                let value = outcome.unwrap();
                if matches!(mode, Mode::Success) {
                    assert_eq!(engine.string_value(&value).unwrap(), "joined");
                } else {
                    let handle = value.heap_handle().expect("result is heap allocated");
                    assert!(matches!(
                        engine.heap.get(handle),
                        Ok(HeapObject::ResultErr(Some(Value::Host(
                            RuntimeValue::Host {
                                kind: RuntimeHostValueKind::FormatError,
                                ..
                            }
                        ))))
                    ));
                }
            }
        }
    }

    #[test]
    fn virtual_time_boundary_restores_the_host_after_malformed_callback_values() {
        #[derive(Default)]
        struct BoundaryHost {
            begun: usize,
            finished: usize,
            invoked: usize,
        }

        impl VmHost for BoundaryHost {
            fn invoke(
                &mut self,
                _name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<RuntimeValue, VmError> {
                self.invoked += 1;
                Ok(RuntimeValue::Unit)
            }

            fn begin_virtual_time(&mut self) -> Result<RuntimeValue, VmError> {
                self.begun += 1;
                Ok(RuntimeValue::Host {
                    kind: RuntimeHostValueKind::VirtualTime,
                    id: 1,
                })
            }

            fn finish_virtual_time(&mut self, _controller: &RuntimeValue) -> Result<(), VmError> {
                self.finished += 1;
                Ok(())
            }
        }

        let mut program = root_pressure_program();
        let int = BytecodeTypeId::new(5);
        let unit = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Unit".into(),
            kind: BytecodeTypeKind::Scalar(BytecodeScalarType::Unit),
        });
        let virtual_time = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "VirtualTime".into(),
            kind: BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::VirtualTime,
                arguments: Vec::new(),
            },
        });
        let body_function = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "fn(ref VirtualTime): Unit".into(),
            kind: BytecodeTypeKind::Function(BytecodeFunctionType {
                is_async: false,
                is_selectable: false,
                is_unsafe: false,
                parameters: vec![BytecodeFunctionParameter {
                    mode: BytecodeParameterMode::Ref,
                    ty: virtual_time,
                }],
                variadic: None,
                outcome: unit,
            }),
        });
        let parameter = BytecodeParameter {
            mode: BytecodeParameterMode::Value,
            ty: int,
            variadic_element: None,
            receiver: false,
        };
        program.callables.extend([
            BytecodeCallable {
                name: "std.testing.withVirtualTime".into(),
                generic_arity: 0,
                parameters: vec![parameter],
                outcome: int,
                function_type: body_function,
                implementation: None,
                closure: None,
            },
            BytecodeCallable {
                name: "host.body".into(),
                generic_arity: 0,
                parameters: vec![BytecodeParameter {
                    mode: BytecodeParameterMode::Ref,
                    ty: virtual_time,
                    variadic_element: None,
                    receiver: false,
                }],
                outcome: unit,
                function_type: body_function,
                implementation: None,
                closure: None,
            },
        ]);
        let trace = derive_trace_metadata(&program).unwrap();
        let boundary = Value::Function {
            callable: BytecodeCallableId::new(0),
            arguments: Vec::new(),
        };

        for (body, invoked) in [
            (Value::Integer(1), 0),
            (
                Value::Function {
                    callable: BytecodeCallableId::new(1),
                    arguments: Vec::new(),
                },
                1,
            ),
        ] {
            let mut host = BoundaryHost::default();
            let error = {
                let mut engine = Engine::new(
                    &program,
                    &mut host,
                    pressure_limits(),
                    ValueCopyStrategy::default(),
                    trace.clone(),
                );
                match engine.prepare_evaluated_call(
                    boundary.clone(),
                    vec![(BytecodeCallArgumentTarget::Fixed(0), body)],
                ) {
                    Err(error) => error,
                    Ok(_) => panic!("malformed virtual-time callback was accepted"),
                }
            };
            assert!(matches!(error, VmError::Invariant(_)));
            assert_eq!((host.begun, host.finished, host.invoked), (1, 1, invoked));
        }

        let mut malformed = program.clone();
        malformed.callables[0].parameters.clear();
        let mut host = BoundaryHost::default();
        let trace = derive_trace_metadata(&malformed).unwrap();
        let result = Engine::new(
            &malformed,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        )
        .prepare_evaluated_call(boundary, Vec::new());
        let error = match result {
            Err(error) => error,
            Ok(_) => panic!("malformed virtual-time boundary was accepted"),
        };
        assert!(
            matches!(error, VmError::Invariant(message) if message.contains("one body operand"))
        );
        assert_eq!((host.begun, host.finished, host.invoked), (0, 0, 0));
    }

    #[test]
    fn host_materialization_accepts_every_supported_shape_and_rejects_drift() {
        let mut program = terminal_fallback_program();
        let append = |program: &mut BytecodeProgram, name: &str, kind: BytecodeTypeKind| {
            let id = BytecodeTypeId::new(program.types.len() as u32);
            program.types.push(BytecodeType {
                name: name.into(),
                kind,
            });
            id
        };
        let unit = append(
            &mut program,
            "Unit",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Unit),
        );
        let boolean = append(
            &mut program,
            "Bool",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Bool),
        );
        let float = append(
            &mut program,
            "Float",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Float),
        );
        let float32 = append(
            &mut program,
            "Float32",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Float32),
        );
        let byte = append(
            &mut program,
            "Byte",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Byte),
        );
        let character = append(
            &mut program,
            "Char",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Char),
        );
        let option = append(
            &mut program,
            "Int?",
            BytecodeTypeKind::Option(BytecodeTypeId::new(5)),
        );
        let result = append(
            &mut program,
            "Int ! String",
            BytecodeTypeKind::Result {
                success: BytecodeTypeId::new(5),
                error: BytecodeTypeId::new(0),
            },
        );
        let union = append(
            &mut program,
            "Int | String",
            BytecodeTypeKind::Union(vec![BytecodeTypeId::new(5), BytecodeTypeId::new(0)]),
        );
        let opaque = append(
            &mut program,
            "impl Copy",
            BytecodeTypeKind::OpaqueResult {
                identity: "test::opaque".into(),
                arguments: Vec::new(),
                witness: BytecodeTypeId::new(5),
                capabilities: BytecodeCapabilitySet {
                    copy: true,
                    discard: true,
                    equatable: true,
                    key: true,
                    send: true,
                    share: true,
                },
            },
        );
        let scalars = append(
            &mut program,
            "(Unit, Bool, Int, Float, Byte, Char)",
            BytecodeTypeKind::Tuple(vec![
                unit,
                boolean,
                BytecodeTypeId::new(5),
                float,
                byte,
                character,
            ]),
        );

        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );

        for (ty, runtime, expected) in [
            (unit, RuntimeValue::Unit, Value::Unit),
            (boolean, RuntimeValue::Bool(true), Value::Bool(true)),
            (
                BytecodeTypeId::new(5),
                RuntimeValue::Integer(42),
                Value::Integer(42),
            ),
            (float, RuntimeValue::Float(1.5), Value::Float(1.5)),
            (
                float32,
                RuntimeValue::Float(16_777_217.0),
                Value::Float(16_777_216.0),
            ),
            (byte, RuntimeValue::Byte(255), Value::Byte(255)),
            (character, RuntimeValue::Char('λ'), Value::Char('λ')),
        ] {
            assert_eq!(
                engine.materialize_host_value(ty, runtime).unwrap(),
                expected
            );
        }

        let tuple = RuntimeValue::Tuple(vec![
            RuntimeValue::Unit,
            RuntimeValue::Bool(true),
            RuntimeValue::Integer(7),
            RuntimeValue::Float(2.5),
            RuntimeValue::Byte(8),
            RuntimeValue::Char('x'),
        ]);
        let value = engine
            .materialize_host_value(scalars, tuple.clone())
            .unwrap();
        assert_eq!(
            snapshot_value(
                &value,
                &engine.heap,
                &engine.callable_names,
                &engine.nominal_names,
            )
            .unwrap(),
            tuple
        );

        for (ty, runtime, expected) in [
            (
                BytecodeTypeId::new(13),
                RuntimeValue::Newtype {
                    name: "TextBox".into(),
                    value: Box::new(RuntimeValue::String("boxed".into())),
                },
                RuntimeValue::Newtype {
                    name: "TextBox".into(),
                    value: Box::new(RuntimeValue::String("boxed".into())),
                },
            ),
            (
                BytecodeTypeId::new(14),
                RuntimeValue::Record {
                    name: "Message".into(),
                    values: vec![
                        RuntimeValue::String("message".into()),
                        RuntimeValue::Array(vec![RuntimeValue::String("tag".into())]),
                    ],
                },
                RuntimeValue::Record {
                    name: "Message".into(),
                    values: vec![
                        RuntimeValue::String("message".into()),
                        RuntimeValue::Array(vec![RuntimeValue::String("tag".into())]),
                    ],
                },
            ),
            (
                BytecodeTypeId::new(15),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 0,
                    values: Vec::new(),
                },
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 0,
                    values: Vec::new(),
                },
            ),
            (
                BytecodeTypeId::new(15),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 1,
                    values: vec![RuntimeValue::String("tuple".into())],
                },
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 1,
                    values: vec![RuntimeValue::String("tuple".into())],
                },
            ),
            (
                BytecodeTypeId::new(15),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 2,
                    values: vec![RuntimeValue::Array(vec![RuntimeValue::String(
                        "record".into(),
                    )])],
                },
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 2,
                    values: vec![RuntimeValue::Array(vec![RuntimeValue::String(
                        "record".into(),
                    )])],
                },
            ),
        ] {
            let value = engine.materialize_host_value(ty, runtime).unwrap();
            assert_eq!(
                snapshot_value(
                    &value,
                    &engine.heap,
                    &engine.callable_names,
                    &engine.nominal_names,
                )
                .unwrap(),
                expected
            );
        }

        for (runtime, expected) in [
            (RuntimeValue::OptionNone, RuntimeValue::OptionNone),
            (
                RuntimeValue::OptionSome(Box::new(RuntimeValue::Integer(9))),
                RuntimeValue::OptionSome(Box::new(RuntimeValue::Integer(9))),
            ),
        ] {
            let value = engine.materialize_host_value(option, runtime).unwrap();
            assert_eq!(
                snapshot_value(
                    &value,
                    &engine.heap,
                    &engine.callable_names,
                    &engine.nominal_names,
                )
                .unwrap(),
                expected
            );
        }
        for runtime in [
            RuntimeValue::ResultOk(Box::new(RuntimeValue::Integer(10))),
            RuntimeValue::ResultErr(Box::new(RuntimeValue::String("error".into()))),
        ] {
            let value = engine
                .materialize_host_value(result, runtime.clone())
                .unwrap();
            assert_eq!(
                snapshot_value(
                    &value,
                    &engine.heap,
                    &engine.callable_names,
                    &engine.nominal_names,
                )
                .unwrap(),
                runtime
            );
        }

        let selected = RuntimeValue::Union {
            member: 5,
            value: Box::new(RuntimeValue::Integer(11)),
        };
        let value = engine
            .materialize_host_value(union, selected.clone())
            .unwrap();
        assert_eq!(
            snapshot_value(
                &value,
                &engine.heap,
                &engine.callable_names,
                &engine.nominal_names,
            )
            .unwrap(),
            selected
        );
        assert_eq!(
            engine
                .materialize_host_value(opaque, RuntimeValue::Integer(12))
                .unwrap(),
            Value::Integer(12)
        );

        assert!(matches!(
            engine.materialize_host_value(boolean, RuntimeValue::Integer(1)),
            Err(VmError::Host(_))
        ));
        assert!(matches!(
            engine.materialize_host_value(
                union,
                RuntimeValue::Union {
                    member: u32::MAX,
                    value: Box::new(RuntimeValue::Integer(1)),
                },
            ),
            Err(VmError::Host(_))
        ));
        assert!(matches!(
            engine.materialize_host_value(scalars, RuntimeValue::Tuple(vec![RuntimeValue::Unit]),),
            Err(VmError::Host(_))
        ));
        for (ty, runtime) in [
            (
                BytecodeTypeId::new(13),
                RuntimeValue::Newtype {
                    name: "Wrong".into(),
                    value: Box::new(RuntimeValue::String("value".into())),
                },
            ),
            (
                BytecodeTypeId::new(14),
                RuntimeValue::Record {
                    name: "Wrong".into(),
                    values: vec![
                        RuntimeValue::String("value".into()),
                        RuntimeValue::Array(Vec::new()),
                    ],
                },
            ),
            (
                BytecodeTypeId::new(14),
                RuntimeValue::Record {
                    name: "Message".into(),
                    values: vec![RuntimeValue::String("missing".into())],
                },
            ),
            (
                BytecodeTypeId::new(15),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 99,
                    values: Vec::new(),
                },
            ),
            (
                BytecodeTypeId::new(15),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 1,
                    values: Vec::new(),
                },
            ),
            (
                BytecodeTypeId::new(15),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 1,
                    values: vec![RuntimeValue::Integer(1)],
                },
            ),
        ] {
            assert!(matches!(
                engine.materialize_host_value(ty, runtime),
                Err(VmError::Host(_))
            ));
        }
        assert!(matches!(
            engine.value_tag(&Value::Integer(1)),
            Err(VmError::Invariant(_))
        ));
        let untagged = engine
            .allocate(
                BytecodeTypeId::new(0),
                super::HeapObject::String("untagged".into()),
                &[],
            )
            .unwrap();
        assert!(matches!(
            engine.value_tag(&untagged),
            Err(VmError::Invariant(_))
        ));
    }

    #[test]
    fn numeric_conversion_and_structural_equality_helpers_are_closed() {
        use BytecodeNumericConversionError::{NotFinite, NotIntegral, OutOfRange};

        assert_eq!(
            convert_numeric(BytecodeScalarType::Bool, &Value::Integer(1)),
            Err(OutOfRange)
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Byte, &Value::Byte(7)),
            Ok(Value::Byte(7))
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Byte, &Value::Float(255.0)),
            Ok(Value::Byte(255))
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Byte, &Value::Float(256.0)),
            Err(OutOfRange)
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Int8, &Value::Float(42.0)),
            Ok(Value::Integer(42))
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Int8, &Value::Float(128.0)),
            Err(OutOfRange)
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Bool, &Value::Float(1.0)),
            Err(OutOfRange)
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Int, &Value::Float(f64::INFINITY)),
            Err(NotFinite)
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Int, &Value::Float(1.5)),
            Err(NotIntegral)
        );
        assert_eq!(
            convert_numeric(BytecodeScalarType::Int, &Value::Unit),
            Err(OutOfRange)
        );

        let mut pending = Vec::new();
        assert!(
            !queue_object_equality(
                &super::HeapObject::Tuple(vec![Some(Value::Integer(1))]),
                &super::HeapObject::Tuple(Vec::new()),
                &mut pending,
            )
            .unwrap()
        );
        assert!(
            !queue_object_equality(
                &super::HeapObject::Newtype {
                    nominal: BytecodeNominalId::new(0),
                    value: Some(Value::Integer(1)),
                },
                &super::HeapObject::Newtype {
                    nominal: BytecodeNominalId::new(1),
                    value: Some(Value::Integer(1)),
                },
                &mut pending,
            )
            .unwrap()
        );
        assert!(
            !queue_object_equality(
                &super::HeapObject::Record {
                    nominal: BytecodeNominalId::new(0),
                    fields: vec![(0, Some(Value::Integer(1)))],
                },
                &super::HeapObject::Record {
                    nominal: BytecodeNominalId::new(0),
                    fields: vec![(1, Some(Value::Integer(1)))],
                },
                &mut pending,
            )
            .unwrap()
        );
        assert!(
            !queue_object_equality(
                &super::HeapObject::Range {
                    kind: BytecodeRangeKind::Exclusive,
                    start: Some(Value::Integer(1)),
                    end: Some(Value::Integer(2)),
                },
                &super::HeapObject::Range {
                    kind: BytecodeRangeKind::Inclusive,
                    start: Some(Value::Integer(1)),
                    end: Some(Value::Integer(2)),
                },
                &mut pending,
            )
            .unwrap()
        );
        assert!(
            queue_object_equality(
                &super::HeapObject::Range {
                    kind: BytecodeRangeKind::Inclusive,
                    start: Some(Value::Integer(1)),
                    end: Some(Value::Integer(2)),
                },
                &super::HeapObject::Range {
                    kind: BytecodeRangeKind::Inclusive,
                    start: Some(Value::Integer(1)),
                    end: Some(Value::Integer(2)),
                },
                &mut pending,
            )
            .unwrap()
        );
        assert!(matches!(
            queue_object_equality(
                &super::HeapObject::Closure {
                    callable: BytecodeCallableId::new(0),
                    captures: Vec::new(),
                },
                &super::HeapObject::Closure {
                    callable: BytecodeCallableId::new(0),
                    captures: Vec::new(),
                },
                &mut pending,
            ),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            queue_object_equality(
                &super::HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(Value::Integer(1)),
                    next: 0,
                    adapter: None,
                },
                &super::HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(Value::Integer(1)),
                    next: 0,
                    adapter: None,
                },
                &mut pending,
            ),
            Err(VmError::Invariant(_))
        ));
        assert!(
            !queue_object_equality(
                &super::HeapObject::OptionNone,
                &super::HeapObject::String("different".into()),
                &mut pending,
            )
            .unwrap()
        );

        assert!(
            !queue_payload_equality(
                &AggregatePayload::Tuple(vec![Some(Value::Integer(1))]),
                &AggregatePayload::Tuple(Vec::new()),
                &mut pending,
            )
            .unwrap()
        );
        assert!(
            !queue_payload_equality(
                &AggregatePayload::Record(vec![(0, Some(Value::Integer(1)))]),
                &AggregatePayload::Record(vec![(1, Some(Value::Integer(1)))]),
                &mut pending,
            )
            .unwrap()
        );
        assert!(
            !queue_payload_equality(
                &AggregatePayload::Unit,
                &AggregatePayload::Tuple(Vec::new()),
                &mut pending,
            )
            .unwrap()
        );

        macro_rules! equal_object {
            ($object:expr) => {{
                let object = $object;
                let clone = object.clone();
                assert!(queue_object_equality(&object, &clone, &mut pending).unwrap());
            }};
        }
        equal_object!(super::HeapObject::String("same".into()));
        equal_object!(super::HeapObject::Tuple(vec![Some(Value::Integer(1))]));
        equal_object!(super::HeapObject::Array(
            vec![Some(Value::Integer(1))].into()
        ));
        equal_object!(super::HeapObject::Newtype {
            nominal: BytecodeNominalId::new(0),
            value: Some(Value::Integer(1)),
        });
        equal_object!(super::HeapObject::Record {
            nominal: BytecodeNominalId::new(0),
            fields: vec![(0, Some(Value::Integer(1)))],
        });
        for payload in [
            AggregatePayload::Unit,
            AggregatePayload::Tuple(vec![Some(Value::Integer(1))]),
            AggregatePayload::Record(vec![(0, Some(Value::Integer(1)))]),
        ] {
            equal_object!(super::HeapObject::Variant {
                variant: 0,
                payload,
            });
        }
        equal_object!(super::HeapObject::OptionNone);
        equal_object!(super::HeapObject::OptionSome(Some(Value::Integer(1))));
        equal_object!(super::HeapObject::ResultOk(Some(Value::Integer(1))));
        equal_object!(super::HeapObject::ResultErr(Some(Value::Integer(1))));
        equal_object!(super::HeapObject::Union {
            member: BytecodeTypeId::new(0),
            value: Some(Value::Integer(1)),
        });
        assert!(
            !queue_object_equality(
                &super::HeapObject::Union {
                    member: BytecodeTypeId::new(0),
                    value: Some(Value::Integer(1)),
                },
                &super::HeapObject::Union {
                    member: BytecodeTypeId::new(1),
                    value: Some(Value::Integer(1)),
                },
                &mut pending,
            )
            .unwrap()
        );
        assert!(
            !queue_object_equality(
                &super::HeapObject::Ref(Some(Value::Integer(1))),
                &super::HeapObject::Ref(Some(Value::Integer(1))),
                &mut pending,
            )
            .unwrap()
        );
    }

    #[test]
    fn projection_and_storage_helper_boundaries_are_closed() {
        let ty = BytecodeTypeId::new(0);
        let slot = |index| BytecodeSlotId::new(index);
        let place = |index| BytecodePlace {
            slot: slot(index),
            ty,
            projections: Vec::new(),
            source_loan: None,
        };
        let operand = |kind| BytecodeOperand { ty, kind };
        for kind in [
            BytecodeOperandKind::Copy(place(1)),
            BytecodeOperandKind::Move(place(2)),
            BytecodeOperandKind::Borrow(place(3)),
        ] {
            let expected = match &kind {
                BytecodeOperandKind::Copy(place)
                | BytecodeOperandKind::Move(place)
                | BytecodeOperandKind::Borrow(place) => place.slot,
                _ => unreachable!(),
            };
            assert_eq!(operand_materialized_slot(&operand(kind)).unwrap(), expected);
        }
        assert!(matches!(
            operand_materialized_slot(&operand(BytecodeOperandKind::Constant(
                BytecodeConstant::Integer("0".into()),
            ))),
            Err(VmError::Invariant(_))
        ));
        let mut projected = place(1);
        projected
            .projections
            .push(crate::bytecode::BytecodeProjection {
                ty,
                kind: crate::bytecode::BytecodeProjectionKind::TupleField(0),
            });
        assert!(matches!(
            operand_materialized_slot(&operand(BytecodeOperandKind::Copy(projected))),
            Err(VmError::Invariant(_))
        ));
        let mut sourced = place(1);
        sourced.source_loan = Some(BytecodeLoanId::new(0));
        assert!(matches!(
            operand_materialized_slot(&operand(BytecodeOperandKind::Copy(sourced))),
            Err(VmError::Invariant(_))
        ));

        let index = BytecodeOperation {
            ty,
            kind: BytecodeOperationKind::Index {
                base: operand(BytecodeOperandKind::Borrow(place(0))),
                index: operand(BytecodeOperandKind::Copy(place(1))),
                access: BytecodeIndexAccess::Array,
                against: Vec::new(),
            },
        };
        let access = operation_access_place(&index).unwrap().unwrap();
        assert!(matches!(
            access.projections.last().map(|projection| &projection.kind),
            Some(crate::bytecode::BytecodeProjectionKind::Index { index, .. })
                if *index == slot(1)
        ));

        let slice = BytecodeOperation {
            ty,
            kind: BytecodeOperationKind::Slice {
                base: operand(BytecodeOperandKind::Borrow(place(0))),
                bounds: Box::new(BytecodeSliceBounds {
                    start: Some(operand(BytecodeOperandKind::Copy(place(1)))),
                    end: Some(operand(BytecodeOperandKind::Move(place(2)))),
                    step: Some(operand(BytecodeOperandKind::Borrow(place(3)))),
                }),
                against: Vec::new(),
            },
        };
        let access = operation_access_place(&slice).unwrap().unwrap();
        assert!(matches!(
            access.projections.last().map(|projection| &projection.kind),
            Some(crate::bytecode::BytecodeProjectionKind::Slice {
                start: Some(start),
                end: Some(end),
                step: Some(step),
            }) if *start == slot(1) && *end == slot(2) && *step == slot(3)
        ));

        let mut invalid_base = index.clone();
        let BytecodeOperationKind::Index { base, .. } = &mut invalid_base.kind else {
            unreachable!()
        };
        base.kind = BytecodeOperandKind::Copy(place(0));
        assert!(matches!(
            operation_access_place(&invalid_base),
            Err(VmError::Invariant(_))
        ));
        let mut invalid_index = index.clone();
        let BytecodeOperationKind::Index { index, .. } = &mut invalid_index.kind else {
            unreachable!()
        };
        index.kind = BytecodeOperandKind::Constant(BytecodeConstant::Integer("0".into()));
        assert!(matches!(
            operation_access_place(&invalid_index),
            Err(VmError::Invariant(_))
        ));
        let unrelated = BytecodeOperation {
            ty,
            kind: BytecodeOperationKind::ExplicitPanic {
                message: operand(BytecodeOperandKind::Constant(BytecodeConstant::String(
                    "\"stop\"".into(),
                ))),
            },
        };
        assert_eq!(operation_access_place(&unrelated).unwrap(), None);

        let path = |root, components| ResolvedPlacePath { root, components };
        let root = (0, 1, 2);
        assert!(paths_overlap(
            &path(root, Vec::new()),
            &path(root, Vec::new())
        ));
        assert!(!paths_overlap(
            &path(root, Vec::new()),
            &path((1, 1, 2), Vec::new())
        ));
        assert!(!paths_overlap(
            &path(root, vec![PlaceComponent::Field(0)]),
            &path(root, vec![PlaceComponent::Field(1)])
        ));
        assert!(paths_overlap(
            &path(root, vec![PlaceComponent::Slice(vec![1, 3])]),
            &path(root, vec![PlaceComponent::Slice(vec![2, 3])])
        ));
        assert!(!paths_overlap(
            &path(root, vec![PlaceComponent::Slice(vec![1, 3])]),
            &path(root, vec![PlaceComponent::Slice(vec![2, 4])])
        ));
        assert!(paths_overlap(
            &path(root, vec![PlaceComponent::Slice(vec![2])]),
            &path(root, vec![PlaceComponent::Index(2)])
        ));
        assert!(paths_overlap(
            &path(root, vec![PlaceComponent::Index(2)]),
            &path(root, vec![PlaceComponent::Slice(vec![2])])
        ));
        assert!(!paths_overlap(
            &path(root, vec![PlaceComponent::Index(-1)]),
            &path(root, vec![PlaceComponent::Slice(vec![usize::MAX])])
        ));
        assert!(!paths_overlap(
            &path(
                root,
                vec![PlaceComponent::MapKey(RuntimeValue::String("a".into()))]
            ),
            &path(
                root,
                vec![PlaceComponent::MapKey(RuntimeValue::String("b".into()))]
            )
        ));

        assert_eq!(slice_indices(None, None, None, 3).unwrap(), [0, 1, 2]);
        assert_eq!(
            slice_indices(Some(-1), None, Some(-1), 3).unwrap(),
            [2, 1, 0]
        );
        assert!(matches!(
            slice_indices(None, None, Some(0), 3),
            Err((PanicCode::ZeroSliceStep, _))
        ));

        let mut values = vec![Some(Value::Integer(1)), None];
        assert_eq!(
            clone_present(&values[0], "value").unwrap(),
            Value::Integer(1)
        );
        assert_eq!(clone_index(&values, 0, "item").unwrap(), Value::Integer(1));
        assert!(clone_index(&values, 1, "item").is_err());
        assert!(clone_index(&values, 2, "item").is_err());
        assert_eq!(
            take_index(&mut values, 0, "item").unwrap(),
            Value::Integer(1)
        );
        assert!(take_index(&mut values, 0, "item").is_err());
        set_index(&mut values, 1, Value::Integer(2), "item").unwrap();
        assert!(set_index(&mut values, 2, Value::Integer(3), "item").is_err());

        let mut fields = vec![(7, Some(Value::Bool(true))), (8, None)];
        assert_eq!(clone_field(&fields, 7, "field").unwrap(), Value::Bool(true));
        assert!(clone_field(&fields, 8, "field").is_err());
        assert!(clone_field(&fields, 9, "field").is_err());
        assert_eq!(
            take_field(&mut fields, 7, "field").unwrap(),
            Value::Bool(true)
        );
        assert!(take_field(&mut fields, 7, "field").is_err());
        set_field(&mut fields, 8, Value::Bool(false)).unwrap();
        assert!(set_field(&mut fields, 9, Value::Bool(false)).is_err());

        let mut optional = Some(Value::Char('T'));
        assert_eq!(present(&optional, "value").unwrap(), &Value::Char('T'));
        assert_eq!(
            take_option(&mut optional, "value").unwrap(),
            Value::Char('T')
        );
        assert!(present(&optional, "value").is_err());
        assert!(take_option(&mut optional, "value").is_err());

        for (scalar, expected) in [
            (BytecodeScalarType::Int, Some((true, 64))),
            (BytecodeScalarType::Int8, Some((true, 8))),
            (BytecodeScalarType::Int16, Some((true, 16))),
            (BytecodeScalarType::Int32, Some((true, 32))),
            (BytecodeScalarType::UInt8, Some((false, 8))),
            (BytecodeScalarType::UInt16, Some((false, 16))),
            (BytecodeScalarType::UInt32, Some((false, 32))),
            (BytecodeScalarType::UInt64, Some((false, 64))),
            (BytecodeScalarType::Float, None),
        ] {
            assert_eq!(integer_shape(scalar), expected);
            assert_eq!(integer_bounds(scalar).is_some(), expected.is_some());
        }
    }

    #[test]
    fn scope_join_search_traverses_every_managed_shape_and_terminates_on_cycles() {
        let mut program = terminal_fallback_program();
        let reference = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Ref[String]".into(),
            kind: BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Ref,
                arguments: vec![BytecodeTypeId::new(0)],
            },
        });
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        let join = Value::Join(RuntimeJoin { task: 3, scope: 7 });

        assert!(
            engine
                .value_contains_scope_join(&join, 7, &mut Default::default())
                .unwrap()
        );
        assert!(
            !engine
                .value_contains_scope_join(&join, 8, &mut Default::default())
                .unwrap()
        );
        assert!(
            !engine
                .any_value_contains_scope_join(
                    [Value::Integer(1), Value::Bool(false)].iter(),
                    7,
                    &mut Default::default(),
                )
                .unwrap()
        );

        macro_rules! assert_nested_join {
            ($ty:expr, $object:expr) => {{
                let value = engine
                    .allocate($ty, $object, std::slice::from_ref(&join))
                    .unwrap();
                assert!(
                    engine
                        .value_contains_scope_join(&value, 7, &mut Default::default())
                        .unwrap()
                );
                assert!(
                    !engine
                        .value_contains_scope_join(&value, 8, &mut Default::default())
                        .unwrap()
                );
            }};
        }

        assert_nested_join!(
            BytecodeTypeId::new(4),
            HeapObject::Tuple(vec![None, Some(join.clone())])
        );
        assert_nested_join!(
            BytecodeTypeId::new(1),
            HeapObject::Array(vec![None, Some(join.clone())].into())
        );
        assert_nested_join!(
            BytecodeTypeId::new(8),
            HeapObject::Set(vec![Some(join.clone())].into())
        );
        assert_nested_join!(
            BytecodeTypeId::new(2),
            HeapObject::Map(vec![(None, Some(join.clone()))].into())
        );
        assert_nested_join!(
            BytecodeTypeId::new(16),
            HeapObject::Closure {
                callable: BytecodeCallableId::new(0),
                captures: vec![None, Some(join.clone())],
            }
        );
        assert_nested_join!(
            BytecodeTypeId::new(13),
            HeapObject::Newtype {
                nominal: BytecodeNominalId::new(0),
                value: Some(join.clone()),
            }
        );
        assert_nested_join!(
            BytecodeTypeId::new(9),
            HeapObject::OptionSome(Some(join.clone()))
        );
        assert_nested_join!(
            BytecodeTypeId::new(10),
            HeapObject::ResultOk(Some(join.clone()))
        );
        assert_nested_join!(
            BytecodeTypeId::new(10),
            HeapObject::ResultErr(Some(join.clone()))
        );
        assert_nested_join!(
            BytecodeTypeId::new(11),
            HeapObject::Union {
                member: BytecodeTypeId::new(0),
                value: Some(join.clone()),
            }
        );
        assert_nested_join!(reference, HeapObject::Ref(Some(join.clone())));
        assert_nested_join!(
            BytecodeTypeId::new(17),
            HeapObject::Iterator {
                mode: BytecodeCursorMode::Ref,
                source: Some(join.clone()),
                next: 0,
                adapter: None,
            }
        );
        assert_nested_join!(
            BytecodeTypeId::new(14),
            HeapObject::Record {
                nominal: BytecodeNominalId::new(1),
                fields: vec![(0, None), (1, Some(join.clone()))],
            }
        );
        assert_nested_join!(
            BytecodeTypeId::new(15),
            HeapObject::Variant {
                variant: 1,
                payload: AggregatePayload::Tuple(vec![Some(join.clone())]),
            }
        );
        assert_nested_join!(
            BytecodeTypeId::new(15),
            HeapObject::Variant {
                variant: 2,
                payload: AggregatePayload::Record(vec![(0, Some(join.clone()))]),
            }
        );
        assert_nested_join!(
            BytecodeTypeId::new(3),
            HeapObject::Range {
                kind: BytecodeRangeKind::Inclusive,
                start: None,
                end: Some(join.clone()),
            }
        );

        for (ty, object) in [
            (
                BytecodeTypeId::new(0),
                HeapObject::String("join-free".into()),
            ),
            (BytecodeTypeId::new(9), HeapObject::OptionNone),
            (
                BytecodeTypeId::new(15),
                HeapObject::Variant {
                    variant: 0,
                    payload: AggregatePayload::Unit,
                },
            ),
            (
                BytecodeTypeId::new(17),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Ref,
                    source: None,
                    next: usize::MAX,
                    adapter: None,
                },
            ),
        ] {
            let value = engine.allocate(ty, object, &[]).unwrap();
            assert!(
                !engine
                    .value_contains_scope_join(&value, 7, &mut Default::default())
                    .unwrap()
            );
        }

        let cycle = engine
            .allocate(BytecodeTypeId::new(9), HeapObject::OptionNone, &[])
            .unwrap();
        let Value::Heap(cycle_handle) = cycle else {
            unreachable!()
        };
        engine
            .replace_object(
                cycle_handle,
                HeapObject::OptionSome(Some(Value::Heap(cycle_handle))),
                &[],
            )
            .unwrap();
        assert!(
            !engine
                .value_contains_scope_join(&cycle, 7, &mut Default::default())
                .unwrap()
        );
    }

    #[test]
    fn cooperative_wakeups_are_idempotent_and_preserve_progress() {
        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine.tasks.push(scheduler_task(TaskStatus::Runnable));

        engine.park_current(TaskWait::Scope, &[1, 1]).unwrap();
        assert_eq!(engine.tasks[1].waiters, [0]);

        engine.wake_task(0).unwrap();
        engine.wake_task(0).unwrap();
        engine.enqueue_task(0).unwrap();
        assert_eq!(engine.runnable.iter().copied().collect::<Vec<_>>(), [0]);
        assert!(engine.tasks[0].queued);

        assert!(engine.schedule_next().unwrap().is_none());
        assert_eq!(engine.current_task, 0);
        assert!(matches!(engine.tasks[0].status, TaskStatus::Running));
        assert!(!engine.tasks[0].queued);
        assert!(engine.runnable.is_empty());
        assert!(engine.resume_current_task().unwrap());
        assert!(engine.tasks[0].resume.is_none());
    }

    #[test]
    fn runnable_tasks_poll_host_completions_without_blocking_the_executor() {
        #[derive(Default)]
        struct ReadyHost {
            polls: usize,
        }

        impl VmHost for ReadyHost {
            fn invoke(
                &mut self,
                name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<RuntimeValue, VmError> {
                Err(VmError::UnsupportedHostCall(name.into()))
            }

            fn poll_async(&mut self, call: u64) -> Result<Option<RuntimeValue>, VmError> {
                self.polls += 1;
                Ok((call == 7).then_some(RuntimeValue::Integer(42)))
            }

            fn wait_async(&mut self, _calls: &[u64]) -> Result<(u64, RuntimeValue), VmError> {
                panic!("the host must not block while a language task is runnable")
            }
        }

        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = ReadyHost::default();
        assert!(matches!(
            host.invoke("unsupported", &[]),
            Err(VmError::UnsupportedHostCall(name)) if name == "unsupported"
        ));
        {
            let mut engine = Engine::new(
                &program,
                &mut host,
                VmLimits::default(),
                ValueCopyStrategy::default(),
                trace,
            );
            engine.tasks.push(scheduler_task(TaskStatus::Running));
            engine
                .tasks
                .push(scheduler_task(TaskStatus::Waiting(TaskWait::HostTask {
                    call: 7,
                    outcome: BytecodeTypeId::new(5),
                })));

            assert!(engine.schedule_next().unwrap().is_none());
            assert!(matches!(
                engine.tasks[1].status,
                TaskStatus::Complete(Some(TaskCompletion::Returned(Value::Integer(42))))
            ));
            assert_eq!(engine.current_task, 0);
        }
        assert_eq!(host.polls, 1);
    }

    #[test]
    fn late_host_completion_is_scheduled_before_quiescence() {
        #[derive(Default)]
        struct DelayedHost {
            polls: usize,
        }

        impl VmHost for DelayedHost {
            fn invoke(
                &mut self,
                name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<RuntimeValue, VmError> {
                Err(VmError::UnsupportedHostCall(name.into()))
            }

            fn poll_async(&mut self, call: u64) -> Result<Option<RuntimeValue>, VmError> {
                self.polls += 1;
                Ok((call == 7 && self.polls == 2).then_some(RuntimeValue::Integer(42)))
            }
        }

        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = DelayedHost::default();
        assert!(matches!(
            host.invoke("unsupported", &[]),
            Err(VmError::UnsupportedHostCall(name)) if name == "unsupported"
        ));
        {
            let mut engine = Engine::new(
                &program,
                &mut host,
                VmLimits::default(),
                ValueCopyStrategy::default(),
                trace,
            );
            engine
                .tasks
                .push(scheduler_task(TaskStatus::Waiting(TaskWait::Scope)));
            engine
                .tasks
                .push(scheduler_task(TaskStatus::Waiting(TaskWait::HostCall {
                    call: 7,
                    outcome: BytecodeTypeId::new(5),
                    destination: BytecodePlace {
                        slot: BytecodeSlotId::new(0),
                        ty: BytecodeTypeId::new(5),
                        projections: Vec::new(),
                        source_loan: None,
                    },
                    target: BytecodeBlockId::new(0),
                    unwind: BytecodeBlockId::new(0),
                    completion: None,
                })));

            assert!(engine.schedule_next().unwrap().is_none());
            assert_eq!(engine.current_task, 1);
            assert!(matches!(engine.tasks[1].status, TaskStatus::Running));
            assert!(engine.runnable.is_empty());
        }
        assert_eq!(host.polls, 2);
    }

    #[test]
    fn float32_rounds_each_operation_and_preserves_ieee_special_values() {
        use BytecodeBinaryOperator::{Add, Divide, Equal, Less, Multiply, NotEqual};

        fn binary(
            engine: &mut Engine<'_, '_>,
            operator: BytecodeBinaryOperator,
            ty: BytecodeTypeId,
            left: f64,
            right: f64,
        ) -> Value {
            engine
                .pure_binary(operator, ty, ty, Value::Float(left), Value::Float(right))
                .unwrap()
        }

        fn float(value: Value) -> f64 {
            let Value::Float(value) = value else {
                panic!("operation did not produce a float")
            };
            value
        }

        let mut program = root_pressure_program();
        let float32 = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Float32".into(),
            kind: BytecodeTypeKind::Scalar(BytecodeScalarType::Float32),
        });
        let float64 = BytecodeTypeId::new(program.types.len() as u32);
        program.types.push(BytecodeType {
            name: "Float".into(),
            kind: BytecodeTypeKind::Scalar(BytecodeScalarType::Float),
        });
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );

        assert_eq!(
            float(binary(&mut engine, Add, float32, 16_777_216.0, 1.0)),
            16_777_216.0
        );
        assert_eq!(
            float(binary(&mut engine, Add, float64, 16_777_216.0, 1.0)),
            16_777_217.0
        );

        let half_ulp = f64::from(f32::from_bits(0x3380_0000));
        assert_eq!(
            float(binary(&mut engine, Add, float32, 1.0, half_ulp)),
            f64::from(f32::from_bits(0x3f80_0000))
        );
        assert_eq!(
            float(binary(
                &mut engine,
                Add,
                float32,
                f64::from(f32::from_bits(0x3f80_0001)),
                half_ulp,
            )),
            f64::from(f32::from_bits(0x3f80_0002))
        );

        let factor = f64::from(f32::from_bits(0x3f80_0001));
        let product = float(binary(&mut engine, Multiply, float32, factor, factor));
        assert_eq!(product, f64::from(f32::from_bits(0x3f80_0002)));
        let separate = float(binary(
            &mut engine,
            Add,
            float32,
            product,
            f64::from(f32::from_bits(0xbf80_0002)),
        ));
        assert_eq!(separate.to_bits(), 0.0_f64.to_bits());

        let factor64 = f64::from_bits(0x3ff0_0000_0000_0001);
        let product64 = float(binary(&mut engine, Multiply, float64, factor64, factor64));
        assert_eq!(product64.to_bits(), 0x3ff0_0000_0000_0002);
        let separate64 = float(binary(
            &mut engine,
            Add,
            float64,
            product64,
            f64::from_bits(0xbff0_0000_0000_0002),
        ));
        assert_eq!(separate64.to_bits(), 0.0_f64.to_bits());

        let subnormal = float(binary(
            &mut engine,
            Divide,
            float32,
            f64::from(f32::from_bits(0x0080_0000)),
            2.0,
        ));
        assert_eq!((subnormal as f32).to_bits(), 0x0040_0000);

        let overflow = float(binary(
            &mut engine,
            Multiply,
            float32,
            f64::from(f32::MAX),
            2.0,
        ));
        assert!(overflow.is_infinite() && overflow.is_sign_positive());

        let negative_infinity = float(binary(&mut engine, Divide, float32, 1.0, -0.0));
        assert!(negative_infinity.is_infinite() && negative_infinity.is_sign_negative());

        let nan = float(binary(&mut engine, Divide, float32, 0.0, 0.0));
        assert!(matches!(
            binary(&mut engine, Equal, float32, nan, nan),
            Value::Bool(false)
        ));
        assert!(matches!(
            binary(&mut engine, NotEqual, float32, nan, nan),
            Value::Bool(true)
        ));
        assert!(matches!(
            binary(&mut engine, Less, float32, nan, 0.0),
            Value::Bool(false)
        ));

        assert_eq!(
            float(
                engine
                    .materialize_host_value(float32, RuntimeValue::Float(16_777_217.0))
                    .unwrap()
            ),
            16_777_216.0
        );
    }

    #[test]
    fn fixed_width_integer_shifts_wrap_and_all_invalid_counts_use_p0010() {
        use BytecodeBinaryOperator::{ShiftLeft, ShiftRight};

        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        for (scalar, signed, bits, minimum, maximum) in [
            (BytecodeScalarType::Byte, false, 8, 0, 255),
            (BytecodeScalarType::UInt8, false, 8, 0, u8::MAX as i128),
            (BytecodeScalarType::UInt16, false, 16, 0, u16::MAX as i128),
            (BytecodeScalarType::UInt32, false, 32, 0, u32::MAX as i128),
            (BytecodeScalarType::UInt64, false, 64, 0, u64::MAX as i128),
            (
                BytecodeScalarType::Int8,
                true,
                8,
                i8::MIN as i128,
                i8::MAX as i128,
            ),
            (
                BytecodeScalarType::Int16,
                true,
                16,
                i16::MIN as i128,
                i16::MAX as i128,
            ),
            (
                BytecodeScalarType::Int32,
                true,
                32,
                i32::MIN as i128,
                i32::MAX as i128,
            ),
            (
                BytecodeScalarType::Int,
                true,
                64,
                i64::MIN as i128,
                i64::MAX as i128,
            ),
        ] {
            let high_bit = 1_i128 << (bits - 1);
            assert_eq!(
                engine
                    .checked_integer_binary(ShiftLeft, scalar, 1, bits - 1)
                    .unwrap(),
                if signed { -high_bit } else { high_bit }
            );
            assert_eq!(
                engine
                    .checked_integer_binary(ShiftLeft, scalar, maximum, 1)
                    .unwrap(),
                if signed { -2 } else { maximum - 1 }
            );
            assert_eq!(
                engine
                    .checked_integer_binary(ShiftLeft, scalar, minimum, 1)
                    .unwrap(),
                0
            );
            assert_eq!(
                engine
                    .checked_integer_binary(
                        ShiftRight,
                        scalar,
                        if signed { -2 } else { maximum },
                        bits - 1,
                    )
                    .unwrap(),
                if signed { -1 } else { 1 }
            );
            assert_eq!(
                engine
                    .checked_integer_binary(ShiftLeft, scalar, maximum, 0)
                    .unwrap(),
                maximum
            );
            for invalid in [-1, bits, i128::from(u64::MAX)] {
                assert_eq!(
                    engine
                        .checked_integer_binary(ShiftLeft, scalar, 1, invalid)
                        .unwrap_err()
                        .0,
                    PanicCode::InvalidShiftCount
                );
            }
        }
    }

    #[test]
    fn checked_integer_arithmetic_uses_the_normative_panic_classes() {
        use BytecodeBinaryOperator::{Add, Divide, Remainder, Subtract};

        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        for (scalar, minimum, maximum) in [
            (BytecodeScalarType::UInt8, 0, u8::MAX as i128),
            (BytecodeScalarType::UInt16, 0, u16::MAX as i128),
            (BytecodeScalarType::UInt32, 0, u32::MAX as i128),
            (BytecodeScalarType::UInt64, 0, u64::MAX as i128),
            (BytecodeScalarType::Int8, i8::MIN as i128, i8::MAX as i128),
            (
                BytecodeScalarType::Int16,
                i16::MIN as i128,
                i16::MAX as i128,
            ),
            (
                BytecodeScalarType::Int32,
                i32::MIN as i128,
                i32::MAX as i128,
            ),
            (BytecodeScalarType::Int, i64::MIN as i128, i64::MAX as i128),
        ] {
            assert_eq!(
                engine
                    .checked_integer_binary(Add, scalar, maximum, 1)
                    .unwrap_err()
                    .0,
                PanicCode::CheckedOverflow
            );
            assert_eq!(
                engine
                    .checked_integer_binary(Subtract, scalar, minimum, 1)
                    .unwrap_err()
                    .0,
                PanicCode::CheckedOverflow
            );
            assert_eq!(
                engine
                    .checked_integer_binary(Divide, scalar, maximum, 0)
                    .unwrap_err()
                    .0,
                PanicCode::IntegerDivisionByZero
            );
            assert_eq!(
                engine
                    .checked_integer_binary(Remainder, scalar, maximum, 0)
                    .unwrap_err()
                    .0,
                PanicCode::IntegerDivisionByZero
            );
            if minimum < 0 {
                assert_eq!(
                    engine
                        .checked_integer_binary(Divide, scalar, minimum, -1)
                        .unwrap_err()
                        .0,
                    PanicCode::CheckedOverflow
                );
                assert_eq!(
                    engine
                        .checked_integer_binary(Remainder, scalar, minimum, -1)
                        .unwrap(),
                    0
                );
            }
        }
    }

    fn string_constant(value: &str) -> BytecodeConstantValue {
        BytecodeConstantValue {
            ty: BytecodeTypeId::new(0),
            kind: BytecodeConstantValueKind::String(value.into()),
        }
    }

    fn string_array_constant(values: &[&str]) -> BytecodeConstantValue {
        BytecodeConstantValue {
            ty: BytecodeTypeId::new(1),
            kind: BytecodeConstantValueKind::Array(
                values.iter().map(|value| string_constant(value)).collect(),
            ),
        }
    }

    #[test]
    fn constant_materialization_roots_completed_children_under_gc_pressure() {
        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        );
        let constant = BytecodeConstantValue {
            ty: BytecodeTypeId::new(4),
            kind: BytecodeConstantValueKind::Tuple(vec![
                string_array_constant(&["left", "right"]),
                BytecodeConstantValue {
                    ty: BytecodeTypeId::new(2),
                    kind: BytecodeConstantValueKind::Map(vec![
                        (
                            string_constant("first"),
                            string_array_constant(&["one", "two"]),
                        ),
                        (
                            string_constant("second"),
                            string_array_constant(&["three", "four"]),
                        ),
                    ]),
                },
            ]),
        };

        let value = engine.materialize_constant(&constant).unwrap();
        let snapshot = snapshot_value(
            &value,
            &engine.heap,
            &engine.callable_names,
            &engine.nominal_names,
        )
        .unwrap();
        assert_eq!(
            snapshot,
            RuntimeValue::Tuple(vec![
                RuntimeValue::Array(vec![
                    RuntimeValue::String("left".into()),
                    RuntimeValue::String("right".into()),
                ]),
                RuntimeValue::Map(vec![
                    (
                        RuntimeValue::String("first".into()),
                        RuntimeValue::Array(vec![
                            RuntimeValue::String("one".into()),
                            RuntimeValue::String("two".into()),
                        ]),
                    ),
                    (
                        RuntimeValue::String("second".into()),
                        RuntimeValue::Array(vec![
                            RuntimeValue::String("three".into()),
                            RuntimeValue::String("four".into()),
                        ]),
                    ),
                ]),
            ])
        );

        let range = BytecodeConstantValue {
            ty: BytecodeTypeId::new(3),
            kind: BytecodeConstantValueKind::Range {
                kind: BytecodeRangeKind::Inclusive,
                start: Box::new(string_constant("a")),
                end: Box::new(string_constant("z")),
            },
        };
        let value = engine.materialize_constant(&range).unwrap();
        let snapshot = snapshot_value(
            &value,
            &engine.heap,
            &engine.callable_names,
            &engine.nominal_names,
        )
        .unwrap();
        assert_eq!(
            snapshot,
            RuntimeValue::Range {
                inclusive: true,
                start: Box::new(RuntimeValue::String("a".into())),
                end: Box::new(RuntimeValue::String("z".into())),
            }
        );
        assert!(engine.statistics.collections > 0);
    }

    #[test]
    fn normalized_constant_materialization_preserves_every_closed_value_shape() {
        let mut program = terminal_fallback_program();
        let append_scalar =
            |program: &mut BytecodeProgram, name: &str, scalar: BytecodeScalarType| {
                let ty = BytecodeTypeId::new(program.types.len() as u32);
                program.types.push(BytecodeType {
                    name: name.into(),
                    kind: BytecodeTypeKind::Scalar(scalar),
                });
                ty
            };
        let unit = append_scalar(&mut program, "Unit", BytecodeScalarType::Unit);
        let boolean = append_scalar(&mut program, "Bool", BytecodeScalarType::Bool);
        let float = append_scalar(&mut program, "Float", BytecodeScalarType::Float);
        let byte = append_scalar(&mut program, "Byte", BytecodeScalarType::Byte);
        let character = append_scalar(&mut program, "Char", BytecodeScalarType::Char);
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        );
        let value = |ty, kind| BytecodeConstantValue { ty, kind };
        let string = |text: &str| {
            value(
                BytecodeTypeId::new(0),
                BytecodeConstantValueKind::String(text.into()),
            )
        };
        let strings = |items: &[&str]| {
            value(
                BytecodeTypeId::new(1),
                BytecodeConstantValueKind::Array(items.iter().map(|item| string(item)).collect()),
            )
        };

        for (constant, expected) in [
            (
                value(unit, BytecodeConstantValueKind::Unit),
                RuntimeValue::Unit,
            ),
            (
                value(boolean, BytecodeConstantValueKind::Bool(true)),
                RuntimeValue::Bool(true),
            ),
            (
                value(
                    BytecodeTypeId::new(5),
                    BytecodeConstantValueKind::Integer(42),
                ),
                RuntimeValue::Integer(42),
            ),
            (
                value(byte, BytecodeConstantValueKind::Integer(255)),
                RuntimeValue::Byte(255),
            ),
            (
                value(float, BytecodeConstantValueKind::Float(1.5_f64.to_bits())),
                RuntimeValue::Float(1.5),
            ),
            (
                value(character, BytecodeConstantValueKind::Char('T')),
                RuntimeValue::Char('T'),
            ),
            (
                value(
                    BytecodeTypeId::new(5),
                    BytecodeConstantValueKind::Function {
                        callable: BytecodeCallableId::new(0),
                        arguments: vec![BytecodeTypeId::new(5)],
                    },
                ),
                RuntimeValue::Function {
                    name: "closure".into(),
                    type_arguments: vec![5],
                },
            ),
            (
                value(
                    BytecodeTypeId::new(8),
                    BytecodeConstantValueKind::Set(vec![string("one"), string("two")]),
                ),
                RuntimeValue::Set(vec![
                    RuntimeValue::String("one".into()),
                    RuntimeValue::String("two".into()),
                ]),
            ),
            (
                value(
                    BytecodeTypeId::new(13),
                    BytecodeConstantValueKind::Newtype {
                        nominal: BytecodeNominalId::new(0),
                        value: Box::new(string("boxed")),
                    },
                ),
                RuntimeValue::Newtype {
                    name: "TextBox".into(),
                    value: Box::new(RuntimeValue::String("boxed".into())),
                },
            ),
            (
                value(
                    BytecodeTypeId::new(14),
                    BytecodeConstantValueKind::Record {
                        nominal: BytecodeNominalId::new(1),
                        fields: vec![(0, string("message")), (1, strings(&["a", "b"]))],
                    },
                ),
                RuntimeValue::Record {
                    name: "Message".into(),
                    values: vec![
                        RuntimeValue::String("message".into()),
                        RuntimeValue::Array(vec![
                            RuntimeValue::String("a".into()),
                            RuntimeValue::String("b".into()),
                        ]),
                    ],
                },
            ),
            (
                value(
                    BytecodeTypeId::new(15),
                    BytecodeConstantValueKind::Variant {
                        variant: 1,
                        payload: BytecodeConstantVariantValue::Tuple(vec![string("tuple")]),
                    },
                ),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 1,
                    values: vec![RuntimeValue::String("tuple".into())],
                },
            ),
            (
                value(
                    BytecodeTypeId::new(15),
                    BytecodeConstantValueKind::Variant {
                        variant: 2,
                        payload: BytecodeConstantVariantValue::Record(vec![(
                            0,
                            strings(&["record"]),
                        )]),
                    },
                ),
                RuntimeValue::Variant {
                    name: "Event".into(),
                    variant: 2,
                    values: vec![RuntimeValue::Array(vec![RuntimeValue::String(
                        "record".into(),
                    )])],
                },
            ),
            (
                value(
                    BytecodeTypeId::new(9),
                    BytecodeConstantValueKind::OptionNone,
                ),
                RuntimeValue::OptionNone,
            ),
            (
                value(
                    BytecodeTypeId::new(9),
                    BytecodeConstantValueKind::OptionSome(Box::new(string("some"))),
                ),
                RuntimeValue::OptionSome(Box::new(RuntimeValue::String("some".into()))),
            ),
            (
                value(
                    BytecodeTypeId::new(10),
                    BytecodeConstantValueKind::ResultOk(Box::new(string("ok"))),
                ),
                RuntimeValue::ResultOk(Box::new(RuntimeValue::String("ok".into()))),
            ),
            (
                value(
                    BytecodeTypeId::new(10),
                    BytecodeConstantValueKind::ResultErr(Box::new(strings(&["error"]))),
                ),
                RuntimeValue::ResultErr(Box::new(RuntimeValue::Array(vec![RuntimeValue::String(
                    "error".into(),
                )]))),
            ),
        ] {
            let materialized = engine.materialize_constant(&constant).unwrap();
            assert_eq!(
                snapshot_value(
                    &materialized,
                    &engine.heap,
                    &engine.callable_names,
                    &engine.nominal_names,
                )
                .unwrap(),
                expected
            );
        }

        assert_eq!(
            engine
                .inline_constant(byte, &BytecodeConstant::Integer("255".into()))
                .unwrap(),
            Value::Byte(255)
        );
        assert!(matches!(
            engine.inline_constant(byte, &BytecodeConstant::Integer("256".into())),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.materialize_constant(&value(byte, BytecodeConstantValueKind::Integer(256),)),
            Err(VmError::Invariant(_))
        ));
    }

    #[test]
    fn runtime_value_algorithms_reject_corruption_and_cover_closed_collection_semantics() {
        let mut program = terminal_fallback_program();
        let append = |program: &mut BytecodeProgram, name: &str, kind: BytecodeTypeKind| {
            let ty = BytecodeTypeId::new(program.types.len() as u32);
            program.types.push(BytecodeType {
                name: name.into(),
                kind,
            });
            ty
        };
        let boolean = append(
            &mut program,
            "Bool",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Bool),
        );
        let byte = append(
            &mut program,
            "Byte",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Byte),
        );
        let float = append(
            &mut program,
            "Float",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Float),
        );
        let character = append(
            &mut program,
            "Char",
            BytecodeTypeKind::Scalar(BytecodeScalarType::Char),
        );
        let reference = append(
            &mut program,
            "Ref[String]",
            BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Ref,
                arguments: vec![BytecodeTypeId::new(0)],
            },
        );
        let mut_cursor = append(
            &mut program,
            "cursor[mut, Array[Int]]",
            BytecodeTypeKind::Cursor {
                mode: BytecodeCursorMode::Mut,
                collection: BytecodeTypeId::new(6),
            },
        );
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );

        let place = BytecodePlace {
            slot: BytecodeSlotId::new(0),
            ty: BytecodeTypeId::new(5),
            projections: Vec::new(),
            source_loan: None,
        };
        assert!(matches!(
            engine.copy_value(&Value::Loan(RuntimeLoan {
                task: 0,
                frame: 0,
                place,
                mode: BytecodeParameterMode::Ref,
            })),
            Err(VmError::Invariant(_))
        ));

        let text = engine
            .allocate(
                BytecodeTypeId::new(0),
                HeapObject::String("éclair".into()),
                &[],
            )
            .unwrap();
        let reference_value = engine
            .allocate(
                reference,
                HeapObject::Ref(Some(text.clone())),
                std::slice::from_ref(&text),
            )
            .unwrap();
        assert_eq!(
            engine.copy_value(&reference_value).unwrap(),
            reference_value
        );

        let empty_array = engine
            .allocate(
                BytecodeTypeId::new(6),
                HeapObject::Array(Vec::new().into()),
                &[],
            )
            .unwrap();
        let ref_cursor = engine
            .allocate(
                BytecodeTypeId::new(17),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Ref,
                    source: Some(empty_array.clone()),
                    next: 3,
                    adapter: None,
                },
                std::slice::from_ref(&empty_array),
            )
            .unwrap();
        let copied_cursor = engine.copy_value(&ref_cursor).unwrap();
        assert_ne!(copied_cursor, ref_cursor);
        let exclusive_cursor = engine
            .allocate(
                mut_cursor,
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Mut,
                    source: Some(empty_array.clone()),
                    next: 0,
                    adapter: None,
                },
                std::slice::from_ref(&empty_array),
            )
            .unwrap();
        assert!(matches!(
            engine.copy_value(&exclusive_cursor),
            Err(VmError::Invariant(_))
        ));

        for value in [
            Value::Unit,
            Value::Bool(true),
            Value::Integer(42),
            Value::Float(1.5),
            Value::Byte(7),
            Value::Char('T'),
            Value::Function {
                callable: BytecodeCallableId::new(0),
                arguments: vec![BytecodeTypeId::new(5)],
            },
        ] {
            assert!(engine.value_equal(&value, &value).unwrap());
        }
        assert!(
            !engine
                .value_equal(&Value::Unit, &Value::Bool(true))
                .unwrap()
        );
        assert!(
            !engine
                .value_equal(&Value::Integer(1), &Value::Integer(2))
                .unwrap()
        );

        let string = |engine: &mut Engine<'_, '_>, value: &str| {
            engine
                .allocate(
                    BytecodeTypeId::new(0),
                    HeapObject::String(value.into()),
                    &[],
                )
                .unwrap()
        };
        let one = string(&mut engine, "one");
        let two = string(&mut engine, "two");
        let three = string(&mut engine, "three");
        let left_set = engine
            .allocate(
                BytecodeTypeId::new(8),
                HeapObject::Set(vec![Some(one.clone()), Some(two.clone())].into()),
                &[one.clone(), two.clone()],
            )
            .unwrap();
        let reordered_set = engine
            .allocate(
                BytecodeTypeId::new(8),
                HeapObject::Set(vec![Some(two.clone()), Some(one.clone())].into()),
                &[one.clone(), two.clone()],
            )
            .unwrap();
        let different_set = engine
            .allocate(
                BytecodeTypeId::new(8),
                HeapObject::Set(vec![Some(one.clone()), Some(three.clone())].into()),
                &[one.clone(), three.clone()],
            )
            .unwrap();
        assert!(engine.value_equal(&left_set, &reordered_set).unwrap());
        assert!(!engine.value_equal(&left_set, &different_set).unwrap());

        let left_map = engine
            .allocate(
                BytecodeTypeId::new(2),
                HeapObject::Map(
                    vec![
                        (Some(one.clone()), Some(two.clone())),
                        (Some(two.clone()), Some(three.clone())),
                    ]
                    .into(),
                ),
                &[one.clone(), two.clone(), three.clone()],
            )
            .unwrap();
        let reordered_map = engine
            .allocate(
                BytecodeTypeId::new(2),
                HeapObject::Map(
                    vec![
                        (Some(two.clone()), Some(three.clone())),
                        (Some(one.clone()), Some(two.clone())),
                    ]
                    .into(),
                ),
                &[one.clone(), two.clone(), three.clone()],
            )
            .unwrap();
        let changed_map = engine
            .allocate(
                BytecodeTypeId::new(2),
                HeapObject::Map(
                    vec![
                        (Some(two.clone()), Some(one.clone())),
                        (Some(one.clone()), Some(two.clone())),
                    ]
                    .into(),
                ),
                &[one.clone(), two.clone()],
            )
            .unwrap();
        assert!(engine.value_equal(&left_map, &reordered_map).unwrap());
        assert!(!engine.value_equal(&left_map, &changed_map).unwrap());

        let first_cycle = engine
            .allocate(BytecodeTypeId::new(9), HeapObject::OptionNone, &[])
            .unwrap();
        let second_cycle = engine
            .allocate(BytecodeTypeId::new(9), HeapObject::OptionNone, &[])
            .unwrap();
        for value in [&first_cycle, &second_cycle] {
            let Value::Heap(handle) = value else {
                unreachable!()
            };
            engine
                .replace_object(
                    *handle,
                    HeapObject::OptionSome(Some(Value::Heap(*handle))),
                    &[],
                )
                .unwrap();
        }
        assert!(engine.value_equal(&first_cycle, &second_cycle).unwrap());

        assert_eq!(
            engine
                .value_order(&Value::Integer(1), &Value::Integer(2))
                .unwrap(),
            Some(std::cmp::Ordering::Less)
        );
        assert_eq!(
            engine
                .value_order(&Value::Float(f64::NAN), &Value::Float(0.0))
                .unwrap(),
            None
        );
        assert_eq!(
            engine
                .value_order(&Value::Byte(2), &Value::Byte(1))
                .unwrap(),
            Some(std::cmp::Ordering::Greater)
        );
        assert_eq!(
            engine
                .value_order(&Value::Char('a'), &Value::Char('a'))
                .unwrap(),
            Some(std::cmp::Ordering::Equal)
        );
        assert_eq!(
            engine.value_order(&one, &two).unwrap(),
            Some(std::cmp::Ordering::Less)
        );
        assert!(matches!(
            engine.value_order(&left_set, &reordered_set),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.value_order(&Value::Unit, &Value::Unit),
            Err(VmError::Invariant(_))
        ));

        let array = engine
            .allocate(
                BytecodeTypeId::new(1),
                HeapObject::Array(vec![Some(one.clone()), Some(two.clone())].into()),
                &[one.clone(), two.clone()],
            )
            .unwrap();
        assert!(
            engine
                .contains(BytecodeContainmentKind::Array, &one, &array)
                .unwrap()
        );
        assert!(
            !engine
                .contains(BytecodeContainmentKind::Array, &three, &array)
                .unwrap()
        );
        assert!(
            engine
                .contains(BytecodeContainmentKind::Set, &two, &left_set)
                .unwrap()
        );
        assert!(
            engine
                .contains(BytecodeContainmentKind::MapKey, &two, &left_map)
                .unwrap()
        );
        let range = engine
            .allocate(
                BytecodeTypeId::new(3),
                HeapObject::Range {
                    kind: BytecodeRangeKind::Exclusive,
                    start: Some(Value::Integer(1)),
                    end: Some(Value::Integer(3)),
                },
                &[],
            )
            .unwrap();
        assert!(
            engine
                .contains(BytecodeContainmentKind::Range, &Value::Integer(2), &range)
                .unwrap()
        );
        assert!(
            !engine
                .contains(BytecodeContainmentKind::Range, &Value::Integer(3), &range)
                .unwrap()
        );
        assert!(
            engine
                .contains(
                    BytecodeContainmentKind::StringChar,
                    &Value::Char('é'),
                    &text
                )
                .unwrap()
        );
        assert!(matches!(
            engine.contains(
                BytecodeContainmentKind::StringChar,
                &Value::Integer(1),
                &text
            ),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.contains(BytecodeContainmentKind::Set, &one, &array),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.contains(BytecodeContainmentKind::Array, &one, &Value::Integer(1),),
            Err(VmError::Invariant(_))
        ));

        assert_eq!(engine.string_value(&text).unwrap(), "éclair");
        assert!(matches!(
            engine.string_value(&Value::Integer(1)),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.string_value(&left_set),
            Err(VmError::Invariant(_))
        ));
        assert_eq!(engine.type_name(BytecodeTypeId::new(5)), "Int");
        assert_eq!(engine.type_name(BytecodeTypeId::new(999)), "<invalid-type>");

        assert!(matches!(
            engine.borrowed_iterator_has_item(&Value::Integer(1), 0),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.borrowed_iterator_has_item(&text, 0),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.iterator_item(&Value::Integer(1), BytecodeTypeId::new(5), 0),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.iterator_item(&array, BytecodeTypeId::new(5), 1),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.iterator_item(&left_set, BytecodeTypeId::new(0), 1),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.iterator_item(&left_map, BytecodeTypeId::new(4), 1),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.iterator_item(&text, character, 1),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.iterator_item(&first_cycle, BytecodeTypeId::new(5), 0),
            Err(VmError::Invariant(_))
        ));
        assert!(matches!(
            engine.range_item(
                BytecodeRangeKind::Exclusive,
                &Value::Integer(1),
                &Value::Char('z'),
                0,
            ),
            Err(VmError::Invariant(_))
        ));
        assert_eq!(
            engine
                .range_item(
                    BytecodeRangeKind::Exclusive,
                    &Value::Char('a'),
                    &Value::Char('c'),
                    3,
                )
                .unwrap(),
            (None, usize::MAX)
        );
        assert_eq!(
            engine
                .range_item(
                    BytecodeRangeKind::Inclusive,
                    &Value::Integer(i128::MAX),
                    &Value::Integer(i128::MAX),
                    1,
                )
                .unwrap(),
            (None, usize::MAX)
        );

        assert_eq!(
            engine
                .checked_prefix(
                    BytecodePrefixOperator::Negate,
                    BytecodeTypeId::new(5),
                    Value::Integer(42),
                )
                .unwrap()
                .unwrap(),
            Value::Integer(-42)
        );
        assert_eq!(
            engine
                .checked_prefix(
                    BytecodePrefixOperator::Negate,
                    BytecodeTypeId::new(5),
                    Value::Integer(i64::MIN as i128),
                )
                .unwrap()
                .unwrap_err()
                .0,
            PanicCode::CheckedOverflow
        );
        assert!(matches!(
            engine.checked_prefix(
                BytecodePrefixOperator::LogicalNot,
                boolean,
                Value::Bool(true),
            ),
            Err(VmError::Invariant(_))
        ));
        assert_eq!(
            engine
                .checked_scalar_binary(
                    BytecodeBinaryOperator::Add,
                    byte,
                    BytecodeTypeId::new(5),
                    Value::Byte(40),
                    Value::Integer(2),
                )
                .unwrap()
                .unwrap(),
            Value::Byte(42)
        );
        assert_eq!(
            engine
                .checked_scalar_binary(
                    BytecodeBinaryOperator::Multiply,
                    byte,
                    byte,
                    Value::Byte(6),
                    Value::Byte(7),
                )
                .unwrap()
                .unwrap(),
            Value::Byte(42)
        );
        assert!(matches!(
            engine.checked_scalar_binary(
                BytecodeBinaryOperator::Add,
                float,
                float,
                Value::Unit,
                Value::Unit,
            ),
            Err(VmError::Invariant(_))
        ));

        for (shape, values) in [
            (
                BytecodeAggregateKind::Closure {
                    callable: BytecodeCallableId::new(0),
                    captures: vec![BytecodeTypeId::new(0)],
                },
                Vec::new(),
            ),
            (
                BytecodeAggregateKind::Newtype {
                    nominal: BytecodeNominalId::new(0),
                },
                Vec::new(),
            ),
            (BytecodeAggregateKind::Ref, Vec::new()),
            (
                BytecodeAggregateKind::Record {
                    nominal: BytecodeNominalId::new(1),
                    fields: vec![0, 1],
                },
                vec![Value::Unit],
            ),
            (
                BytecodeAggregateKind::Variant {
                    variant: 1,
                    fields: vec![None],
                },
                Vec::new(),
            ),
            (
                BytecodeAggregateKind::Variant {
                    variant: 2,
                    fields: vec![Some(0), None],
                },
                vec![Value::Unit, Value::Unit],
            ),
            (BytecodeAggregateKind::OptionNone, vec![Value::Unit]),
            (BytecodeAggregateKind::OptionSome, Vec::new()),
            (BytecodeAggregateKind::ResultOk, Vec::new()),
            (BytecodeAggregateKind::ResultErr, Vec::new()),
        ] {
            assert!(matches!(
                engine.construct_aggregate(BytecodeTypeId::new(9), &shape, values),
                Err(VmError::Invariant(_))
            ));
        }
    }

    #[test]
    fn eager_cursor_copy_owns_an_independent_source_and_position() {
        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::Eager,
            trace,
        );
        let source = engine
            .materialize_constant(&BytecodeConstantValue {
                ty: BytecodeTypeId::new(6),
                kind: BytecodeConstantValueKind::Array(vec![
                    BytecodeConstantValue {
                        ty: BytecodeTypeId::new(5),
                        kind: BytecodeConstantValueKind::Integer(1),
                    },
                    BytecodeConstantValue {
                        ty: BytecodeTypeId::new(5),
                        kind: BytecodeConstantValueKind::Integer(2),
                    },
                ]),
            })
            .unwrap();
        let original = engine
            .allocate(
                BytecodeTypeId::new(7),
                super::HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(source.clone()),
                    next: 1,
                    adapter: None,
                },
                std::slice::from_ref(&source),
            )
            .unwrap();
        let allocations = engine.statistics.allocations;
        let copied = engine.copy_value(&original).unwrap();
        assert_eq!(engine.statistics.allocations, allocations + 2);

        let (Value::Heap(original), Value::Heap(copied)) = (original, copied) else {
            unreachable!("managed cursors use heap handles")
        };
        assert_ne!(original, copied);
        let super::HeapObject::Iterator {
            mode: original_mode,
            source: original_source,
            next: original_next,
            adapter: _,
        } = engine.heap.get(original).unwrap().clone()
        else {
            unreachable!("the original cursor retains its iterator shape")
        };
        let super::HeapObject::Iterator {
            mode: copied_mode,
            source: copied_source,
            next: copied_next,
            adapter: _,
        } = engine.heap.get(copied).unwrap().clone()
        else {
            unreachable!("the copied cursor retains its iterator shape")
        };
        assert_eq!(original_mode, BytecodeCursorMode::Own);
        assert_eq!(copied_mode, BytecodeCursorMode::Own);
        assert_eq!(original_next, 1);
        assert_eq!(copied_next, 1);
        assert_ne!(
            original_source.unwrap().heap_handle(),
            copied_source.unwrap().heap_handle(),
            "owning cursor copies must not share their destructively advanced collection"
        );

        engine
            .replace_object(
                original,
                super::HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(source),
                    next: 2,
                    adapter: None,
                },
                &[],
            )
            .unwrap();
        assert!(matches!(
            engine.heap.get(copied).unwrap(),
            super::HeapObject::Iterator { next: 1, .. }
        ));
    }

    #[test]
    fn host_materialization_roots_completed_children_under_gc_pressure() {
        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        );
        let returned = RuntimeValue::Tuple(vec![
            RuntimeValue::Array(vec![
                RuntimeValue::String("left".into()),
                RuntimeValue::String("right".into()),
            ]),
            RuntimeValue::Array(vec![
                RuntimeValue::String("up".into()),
                RuntimeValue::String("down".into()),
            ]),
        ]);

        let value = engine
            .materialize_host_value(BytecodeTypeId::new(4), returned.clone())
            .unwrap();
        let snapshot = snapshot_value(
            &value,
            &engine.heap,
            &engine.callable_names,
            &engine.nominal_names,
        )
        .unwrap();
        assert_eq!(snapshot, returned);
        assert!(engine.statistics.collections > 0);
    }

    #[test]
    fn detached_host_snapshots_do_not_become_vm_roots() {
        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        );
        let managed = engine
            .allocate(
                BytecodeTypeId::new(0),
                super::HeapObject::String("host-owned".into()),
                &[],
            )
            .unwrap();
        let retained_by_host = snapshot_value(
            &managed,
            &engine.heap,
            &engine.callable_names,
            &engine.nominal_names,
        )
        .unwrap();

        engine
            .allocate(
                BytecodeTypeId::new(0),
                super::HeapObject::String("pressure".into()),
                &[],
            )
            .unwrap();

        assert_eq!(retained_by_host, RuntimeValue::String("host-owned".into()));
        assert!(
            snapshot_value(
                &managed,
                &engine.heap,
                &engine.callable_names,
                &engine.nominal_names,
            )
            .is_err()
        );
        assert!(engine.statistics.reclaimed_objects > 0);
    }

    #[test]
    fn structured_pending_values_publish_and_withdraw_temporary_roots() {
        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            pressure_limits(),
            ValueCopyStrategy::default(),
            trace,
        );
        let retained = engine
            .allocate(
                BytecodeTypeId::new(0),
                super::HeapObject::String("retained".into()),
                &[],
            )
            .unwrap();
        let marker = engine.temporary_roots.len();
        let mut pending = Vec::new();
        engine.queue_fallback_value(
            &mut pending,
            RuntimeType {
                ty: BytecodeTypeId::new(0),
                substitutions: Vec::new(),
            },
            retained.clone(),
        );

        engine
            .allocate(
                BytecodeTypeId::new(0),
                super::HeapObject::String("pressure".into()),
                &[],
            )
            .unwrap();
        assert_eq!(
            snapshot_value(
                &retained,
                &engine.heap,
                &engine.callable_names,
                &engine.nominal_names,
            )
            .unwrap(),
            RuntimeValue::String("retained".into())
        );

        pending.clear();
        engine.temporary_roots.truncate(marker);
        engine
            .allocate(
                BytecodeTypeId::new(0),
                super::HeapObject::String("after-withdrawal".into()),
                &[],
            )
            .unwrap();
        assert!(matches!(retained, Value::Heap(_)));
        assert!(
            snapshot_value(
                &retained,
                &engine.heap,
                &engine.callable_names,
                &engine.nominal_names,
            )
            .is_err()
        );
        assert!(engine.statistics.reclaimed_objects > 0);
    }

    #[test]
    fn iterator_contract_helpers_reject_malformed_descriptors_and_states() {
        let mut program = terminal_fallback_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let add_type =
            |program: &mut BytecodeProgram, name: &str, kind: BytecodeTypeKind| -> BytecodeTypeId {
                let id = BytecodeTypeId::new(program.types.len() as u32);
                program.types.push(BytecodeType {
                    name: name.into(),
                    kind,
                });
                id
            };
        let string = BytecodeTypeId::new(0);
        let strings = BytecodeTypeId::new(1);
        let int = BytecodeTypeId::new(5);
        let ints = BytecodeTypeId::new(6);
        let non_array_cursor = add_type(
            &mut program,
            "cursor[own, String]",
            BytecodeTypeKind::Cursor {
                mode: BytecodeCursorMode::Own,
                collection: string,
            },
        );
        let empty_array = add_type(
            &mut program,
            "Array[]",
            BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Array,
                arguments: Vec::new(),
            },
        );
        let empty_cursor = add_type(
            &mut program,
            "cursor[own, Array[]]",
            BytecodeTypeKind::Cursor {
                mode: BytecodeCursorMode::Own,
                collection: empty_array,
            },
        );
        let empty_result = add_type(
            &mut program,
            "Array[] ! String",
            BytecodeTypeKind::Result {
                success: empty_array,
                error: string,
            },
        );
        let int_result = add_type(
            &mut program,
            "Array[Int] ! Array[String]",
            BytecodeTypeKind::Result {
                success: ints,
                error: strings,
            },
        );
        let bad_map = add_type(
            &mut program,
            "Map[String]",
            BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Map,
                arguments: vec![string],
            },
        );
        let bad_set = add_type(
            &mut program,
            "Set[]",
            BytecodeTypeKind::Intrinsic {
                constructor: BytecodeIntrinsicType::Set,
                arguments: Vec::new(),
            },
        );
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );

        assert!(matches!(
            engine.normalize_iterator_source(&Value::Integer(1), BytecodeTypeId::new(7)),
            Err(VmError::Invariant(message)) if message.contains("not a managed iterable")
        ));
        let option = engine
            .allocate(BytecodeTypeId::new(9), HeapObject::OptionNone, &[])
            .unwrap();
        assert!(matches!(
            engine.normalize_iterator_source(&option, BytecodeTypeId::new(7)),
            Err(VmError::Invariant(message)) if message.contains("not an owning iterable")
        ));

        let array = engine
            .allocate(
                ints,
                HeapObject::Array(vec![Some(Value::Integer(1)), Some(Value::Integer(2))].into()),
                &[],
            )
            .unwrap();
        let normalized = engine
            .normalize_iterator_source(&array, BytecodeTypeId::new(7))
            .unwrap();
        assert!(matches!(
            engine.heap.get(normalized.heap_handle().unwrap()).unwrap(),
            HeapObject::Iterator {
                mode: BytecodeCursorMode::Own,
                adapter: None,
                ..
            }
        ));
        let own_cursor = engine
            .allocate(
                BytecodeTypeId::new(7),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(array.clone()),
                    next: 0,
                    adapter: None,
                },
                std::slice::from_ref(&array),
            )
            .unwrap();
        assert_eq!(
            engine
                .normalize_iterator_source(&own_cursor, BytecodeTypeId::new(7))
                .unwrap(),
            own_cursor
        );
        for source in [
            engine
                .allocate(string, HeapObject::String("text".into()), &[])
                .unwrap(),
            engine
                .allocate(
                    BytecodeTypeId::new(2),
                    HeapObject::Map(vec![(Some(Value::Integer(1)), Some(array.clone()))].into()),
                    std::slice::from_ref(&array),
                )
                .unwrap(),
            engine
                .allocate(
                    BytecodeTypeId::new(8),
                    HeapObject::Set(vec![Some(Value::Integer(1))].into()),
                    &[],
                )
                .unwrap(),
            engine
                .allocate(
                    BytecodeTypeId::new(3),
                    HeapObject::Range {
                        kind: BytecodeRangeKind::Exclusive,
                        start: Some(Value::Integer(0)),
                        end: Some(Value::Integer(2)),
                    },
                    &[],
                )
                .unwrap(),
        ] {
            assert!(
                engine
                    .normalize_iterator_source(&source, BytecodeTypeId::new(7))
                    .is_ok()
            );
        }

        assert!(
            engine
                .cursor_array_element_type(BytecodeTypeId::new(999))
                .is_err()
        );
        assert!(engine.cursor_array_element_type(string).is_err());
        assert!(engine.cursor_array_element_type(non_array_cursor).is_err());
        assert!(engine.cursor_array_element_type(empty_cursor).is_err());
        assert_eq!(
            engine
                .cursor_array_element_type(BytecodeTypeId::new(7))
                .unwrap(),
            int
        );
        assert!(engine.result_array_type(BytecodeTypeId::new(999)).is_err());
        assert!(engine.result_array_type(string).is_err());
        assert!(engine.result_array_type(BytecodeTypeId::new(10)).is_err());
        assert!(engine.result_array_type(empty_result).is_err());
        assert_eq!(engine.result_array_type(int_result).unwrap(), (ints, int));
        assert!(matches!(
            engine.materialize_host_value(bad_map, RuntimeValue::Map(Vec::new())),
            Err(VmError::Invariant(message)) if message.contains("map type has the wrong arity")
        ));
        assert!(matches!(
            engine.materialize_host_value(bad_set, RuntimeValue::Set(Vec::new())),
            Err(VmError::Invariant(message)) if message.contains("set type has the wrong arity")
        ));
        let host_array = engine
            .materialize_host_value(
                strings,
                RuntimeValue::Array(vec![RuntimeValue::String("array".into())]),
            )
            .unwrap();
        assert!(matches!(
            engine.heap.get(host_array.heap_handle().unwrap()).unwrap(),
            HeapObject::Array(_)
        ));
        let host_map = engine
            .materialize_host_value(
                BytecodeTypeId::new(2),
                RuntimeValue::Map(vec![(
                    RuntimeValue::String("key".into()),
                    RuntimeValue::Array(vec![RuntimeValue::String("value".into())]),
                )]),
            )
            .unwrap();
        assert!(matches!(
            engine.heap.get(host_map.heap_handle().unwrap()).unwrap(),
            HeapObject::Map(_)
        ));
        let host_set = engine
            .materialize_host_value(
                BytecodeTypeId::new(8),
                RuntimeValue::Set(vec![RuntimeValue::String("set".into())]),
            )
            .unwrap();
        assert!(matches!(
            engine.heap.get(host_set.heap_handle().unwrap()).unwrap(),
            HeapObject::Set(_)
        ));

        assert!(matches!(
            engine.next_owned_iterator_value(&Value::Integer(1), int),
            Err(VmError::Invariant(message)) if message.contains("not a managed cursor")
        ));
        assert!(matches!(
            engine.next_owned_iterator_value(&array, int),
            Err(VmError::Invariant(message)) if message.contains("wrong heap shape")
        ));
        let borrowed_cursor = engine
            .allocate(
                BytecodeTypeId::new(17),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Ref,
                    source: Some(array.clone()),
                    next: 0,
                    adapter: None,
                },
                std::slice::from_ref(&array),
            )
            .unwrap();
        assert!(matches!(
            engine.next_owned_iterator_value(&borrowed_cursor, int),
            Err(VmError::Invariant(message)) if message.contains("not an owning cursor")
        ));
        let exhausted_cursor = engine
            .allocate(
                BytecodeTypeId::new(7),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(array.clone()),
                    next: usize::MAX,
                    adapter: None,
                },
                std::slice::from_ref(&array),
            )
            .unwrap();
        assert_eq!(
            engine
                .next_owned_iterator_value(&exhausted_cursor, int)
                .unwrap()
                .unwrap(),
            None
        );
        let missing_source = engine
            .allocate(
                BytecodeTypeId::new(7),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: None,
                    next: 0,
                    adapter: None,
                },
                &[],
            )
            .unwrap();
        assert!(matches!(
            engine.next_owned_iterator_value(&missing_source, int),
            Err(VmError::Invariant(message)) if message.contains("iterator source")
        ));
        let (step, adapter, next) = engine
            .iterator_adapter_next(
                &Value::Integer(1),
                IteratorAdapter::Take {
                    remaining: 0,
                    source_item: int,
                },
                int,
            )
            .unwrap();
        assert!(step.is_none());
        assert_eq!(next, usize::MAX);
        assert!(matches!(
            adapter,
            IteratorAdapter::Take { remaining: 0, .. }
        ));

        let state = BytecodePlace {
            slot: BytecodeSlotId::new(0),
            ty: BytecodeTypeId::new(7),
            projections: Vec::new(),
            source_loan: None,
        };
        let span = BytecodeSpan {
            file: 0,
            start: 0,
            end: 0,
        };
        let fallback = install_fallback_frame(&mut engine, int, Value::Integer(1));
        assert!(matches!(
            engine.iterator_next(0, &fallback.owner, None, int, span),
            Err(VmError::Invariant(message)) if message.contains("not managed")
        ));
        engine.frames[0].slots[0] = SlotState::Value(array.clone());
        assert!(matches!(
            engine.iterator_next(0, &state, None, int, span),
            Err(VmError::Invariant(message)) if message.contains("wrong heap shape")
        ));
        engine.frames[0].slots[0] = SlotState::Value(exhausted_cursor.clone());
        assert!(matches!(
            engine.iterator_next(0, &state, None, int, span),
            Ok(Ok(None))
        ));
        let adapter_cursor = engine
            .allocate(
                BytecodeTypeId::new(17),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Ref,
                    source: Some(array.clone()),
                    next: 0,
                    adapter: Some(IteratorAdapter::Take {
                        remaining: 0,
                        source_item: int,
                    }),
                },
                std::slice::from_ref(&array),
            )
            .unwrap();
        engine.frames[0].slots[0] = SlotState::Value(adapter_cursor);
        assert!(matches!(
            engine.iterator_next(0, &state, None, int, span),
            Err(VmError::Invariant(message)) if message.contains("lazy iterator adapter")
        ));
        let owning_adapter = engine
            .allocate(
                BytecodeTypeId::new(7),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(array.clone()),
                    next: 0,
                    adapter: Some(IteratorAdapter::Take {
                        remaining: 0,
                        source_item: int,
                    }),
                },
                std::slice::from_ref(&array),
            )
            .unwrap();
        engine.frames[0].slots[0] = SlotState::Value(owning_adapter);
        assert!(matches!(
            engine.iterator_next(0, &state, Some(&state), int, span),
            Err(VmError::Invariant(message)) if message.contains("lazy iterator adapter")
        ));
        let owning_cursor = engine
            .allocate(
                BytecodeTypeId::new(7),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Own,
                    source: Some(array.clone()),
                    next: 0,
                    adapter: None,
                },
                std::slice::from_ref(&array),
            )
            .unwrap();
        engine.frames[0].slots[0] = SlotState::Value(owning_cursor);
        assert!(matches!(
            engine.iterator_next(0, &state, Some(&state), int, span),
            Err(VmError::Invariant(message)) if message.contains("owning iterator")
        ));
        let ref_state = engine
            .allocate(
                BytecodeTypeId::new(17),
                HeapObject::Iterator {
                    mode: BytecodeCursorMode::Ref,
                    source: Some(array.clone()),
                    next: 0,
                    adapter: None,
                },
                std::slice::from_ref(&array),
            )
            .unwrap();
        engine.frames[0].slots[0] = SlotState::Value(ref_state);
        assert!(matches!(
            engine.iterator_next(0, &state, None, int, span),
            Err(VmError::Invariant(message)) if message.contains("no source place")
        ));
        let other_array = engine
            .allocate(
                ints,
                HeapObject::Array(vec![Some(Value::Integer(9))].into()),
                &[],
            )
            .unwrap();
        engine.frames[0].slots.push(SlotState::Value(other_array));
        engine.frame_traces[0].slots.push(ints);
        let borrowed_place = BytecodePlace {
            slot: BytecodeSlotId::new(1),
            ty: ints,
            projections: Vec::new(),
            source_loan: None,
        };
        assert!(matches!(
            engine.iterator_next(0, &state, Some(&borrowed_place), int, span),
            Err(VmError::Invariant(message)) if message.contains("differs")
        ));
        engine.frames[0].slots[1] = SlotState::Value(array);
        assert!(matches!(
            engine.iterator_next(0, &state, Some(&borrowed_place), int, span),
            Ok(Ok(Some(super::IteratorStep::Position(0))))
        ));
    }

    #[test]
    fn diagnostic_execution_is_opt_in_and_captures_runtime_boundaries() {
        let string = BytecodeTypeId::new(0);
        let function_type = BytecodeTypeId::new(1);
        let span = BytecodeSpan {
            file: 7,
            start: 10,
            end: 20,
        };
        let destination = BytecodePlace {
            slot: BytecodeSlotId::new(0),
            ty: string,
            projections: Vec::new(),
            source_loan: None,
        };
        let program = BytecodeProgram {
            types: vec![
                BytecodeType {
                    name: "String".into(),
                    kind: BytecodeTypeKind::Scalar(BytecodeScalarType::String),
                },
                BytecodeType {
                    name: "fn main(): String".into(),
                    kind: BytecodeTypeKind::Function(BytecodeFunctionType {
                        is_async: false,
                        is_selectable: false,
                        is_unsafe: false,
                        parameters: Vec::new(),
                        variadic: None,
                        outcome: string,
                    }),
                },
            ],
            nominals: Vec::new(),
            callables: vec![BytecodeCallable {
                name: "main".into(),
                generic_arity: 0,
                parameters: Vec::new(),
                outcome: string,
                function_type,
                implementation: Some(BytecodeFunctionId::new(0)),
                closure: None,
            }],
            constants: Vec::new(),
            functions: vec![BytecodeFunction {
                callable: BytecodeCallableId::new(0),
                source: span,
                types: vec![string],
                spans: vec![span],
                slots: vec![BytecodeSlot {
                    ty: string,
                    span: crate::bytecode::BytecodeSpanId::new(0),
                    kind: BytecodeSlotKind::Return,
                }],
                loans: Vec::new(),
                parameters: Vec::new(),
                return_slot: BytecodeSlotId::new(0),
                entry: BytecodeBlockId::new(0),
                unwind: BytecodeBlockId::new(1),
                blocks: vec![
                    BytecodeBlock {
                        kind: BytecodeBlockKind::Normal,
                        instructions: vec![BytecodeInstruction {
                            span: crate::bytecode::BytecodeSpanId::new(0),
                            kind: BytecodeInstructionKind::Store {
                                destination,
                                value: BytecodeRvalue {
                                    ty: string,
                                    kind: BytecodeRvalueKind::Use(BytecodeOperand {
                                        ty: string,
                                        kind: BytecodeOperandKind::Constant(
                                            BytecodeConstant::String("\"diagnostic\"".into()),
                                        ),
                                    }),
                                },
                            },
                        }],
                        terminator: BytecodeTerminator {
                            span: crate::bytecode::BytecodeSpanId::new(0),
                            kind: BytecodeTerminatorKind::Return,
                        },
                    },
                    BytecodeBlock {
                        kind: BytecodeBlockKind::Cleanup,
                        instructions: Vec::new(),
                        terminator: BytecodeTerminator {
                            span: crate::bytecode::BytecodeSpanId::new(0),
                            kind: BytecodeTerminatorKind::ResumePanic,
                        },
                    },
                ],
            }],
        };

        let mut normal_host = RejectingHost;
        let normal = execute(&program, BytecodeFunctionId::new(0), &mut normal_host).unwrap();
        assert!(normal.diagnostics.is_none());

        let mut diagnostic_host = RejectingHost;
        let observed = execute_with_diagnostics(
            &program,
            BytecodeFunctionId::new(0),
            &mut diagnostic_host,
            DiagnosticConfig {
                max_events: 64,
                ..DiagnosticConfig::default()
            },
        )
        .unwrap();
        assert!(matches!(
            observed.outcome,
            VmOutcome::Returned(RuntimeValue::String(value)) if value == "diagnostic"
        ));
        let trace = observed.diagnostics.expect("diagnostics were requested");
        assert_eq!(trace.format, super::super::diagnostics::DIAGNOSTIC_SCHEMA);
        assert_eq!(trace.task_ids(), [1]);
        let race = super::super::race::detect_races(&trace);
        assert!(
            race.is_clean(),
            "single-task trace must be race-clean: {race:?}"
        );
        let leaks = super::super::leak::detect_leaks(&trace);
        assert!(
            leaks.is_clean(),
            "a single returned value is not a retention finding: {leaks:?}"
        );
        assert!(trace.events.iter().any(|event| matches!(
            event,
            DiagnosticEvent::Memory {
                access: DiagnosticMemoryAccess::Write,
                source: DiagnosticSource {
                    function,
                    span: observed_span,
                },
                ..
            } if function == "main" && *observed_span == span
        )));
        assert!(trace.events.iter().any(|event| matches!(
            event,
            DiagnosticEvent::Heap {
                operation: super::super::diagnostics::DiagnosticHeapOperation::Allocate,
                ..
            }
        )));
        assert!(trace.events.iter().any(|event| matches!(
            event,
            DiagnosticEvent::Thread {
                state: DiagnosticThreadState::Started,
                ..
            }
        )));
        assert!(
            trace
                .events
                .iter()
                .any(|event| matches!(event, DiagnosticEvent::Roots { .. }))
        );
        assert!(!trace.is_truncated());
        let dump = super::super::dump::capture_dump(
            &trace,
            super::super::dump::DumpIdentity {
                run_id: "runtime-test".into(),
                attempt_id: "attempt-1".into(),
                shard: "0/1".into(),
                profile: "crash".into(),
                target: "linux-x86_64".into(),
                backend: "bytecode-vm".into(),
                toolchain: "test".into(),
                source_revision: "test-revision".into(),
            },
            super::super::dump::DumpTermination {
                reason: "returned".into(),
                program_exit_status: Some(0),
                command_exit_status: Some(0),
            },
        )
        .unwrap();
        let dump_analysis = super::super::dump::analyze_dump(&dump).unwrap();
        assert_eq!(dump_analysis.task_count, 1);
        assert_eq!(dump_analysis.thread_count, 1);
        assert!(!dump_analysis.truncated);

        let mut repeat_host = RejectingHost;
        let repeat = execute_with_diagnostics(
            &program,
            BytecodeFunctionId::new(0),
            &mut repeat_host,
            DiagnosticConfig {
                max_events: 64,
                ..DiagnosticConfig::default()
            },
        )
        .unwrap()
        .diagnostics
        .unwrap();
        assert_eq!(trace.events, repeat.events);
        assert_eq!(trace.source_maps, repeat.source_maps);

        let mut limited_host = RejectingHost;
        let limited = execute_with_diagnostics(
            &program,
            BytecodeFunctionId::new(0),
            &mut limited_host,
            DiagnosticConfig {
                max_events: 1,
                ..DiagnosticConfig::default()
            },
        )
        .unwrap_err();
        assert!(matches!(
            limited,
            VmError::ResourceLimit {
                resource: "diagnostic events",
                limit: 1
            }
        ));
    }

    #[test]
    fn diagnostic_engine_records_internal_scheduler_and_resource_boundaries() {
        struct AsyncHost;

        impl VmHost for AsyncHost {
            fn invoke(
                &mut self,
                name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<RuntimeValue, VmError> {
                Err(VmError::UnsupportedHostCall(name.to_owned()))
            }

            fn start_async(
                &mut self,
                _name: &str,
                _arguments: &[RuntimeValue],
            ) -> Result<u64, VmError> {
                Ok(41)
            }
        }

        let program = root_pressure_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let session =
            super::super::diagnostics::DiagnosticSession::new(DiagnosticConfig::default()).unwrap();
        let mut host = AsyncHost;
        let mut engine = Engine::new_with_diagnostics(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
            Some(session),
        );
        engine.tasks.push(scheduler_task(TaskStatus::Running));

        engine
            .record_thread(DiagnosticThreadState::Stopped)
            .unwrap();
        engine
            .record_task(
                0,
                None,
                super::super::diagnostics::DiagnosticTaskState::Created,
            )
            .unwrap();
        engine
            .record_new_task(
                0,
                None,
                super::super::diagnostics::DiagnosticTaskState::Running,
            )
            .unwrap();
        engine
            .record_scheduler(
                0,
                super::super::diagnostics::DiagnosticSchedulerOperation::Switch,
            )
            .unwrap();
        engine
            .record_sync(
                0,
                super::super::diagnostics::DiagnosticSynchronization::HostStart,
                Some(1),
                None,
            )
            .unwrap();
        engine
            .record_quiescence(super::super::diagnostics::DiagnosticQuiescencePhase::Begin)
            .unwrap();

        let place = BytecodePlace {
            slot: BytecodeSlotId::new(0),
            ty: BytecodeTypeId::new(0),
            projections: Vec::new(),
            source_loan: None,
        };
        engine
            .record_memory(0, &place, DiagnosticMemoryAccess::Read)
            .unwrap();
        let value = engine
            .allocate(
                BytecodeTypeId::new(0),
                HeapObject::String("diagnostic".into()),
                &[],
            )
            .unwrap();
        let handle = value.heap_handle().unwrap();
        engine
            .record_heap(
                handle,
                super::super::diagnostics::DiagnosticHeapOperation::Replace,
                1,
            )
            .unwrap();
        engine.record_roots(std::slice::from_ref(&value)).unwrap();
        let host_value = RuntimeValue::Host {
            kind: RuntimeHostValueKind::File,
            id: 9,
        };
        engine
            .record_resource(
                &host_value,
                super::super::diagnostics::DiagnosticResourceState::Acquired,
            )
            .unwrap();
        engine.cleanup_host_value(&host_value).unwrap();
        assert_eq!(engine.start_host_async("read", &[], None).unwrap(), 41);

        engine.frames.push(Frame {
            function: BytecodeFunctionId::new(0),
            block: BytecodeBlockId::new(0),
            instruction: 0,
            slots: vec![
                SlotState::Value(value.clone()),
                SlotState::Dead,
                SlotState::Uninitialized,
            ],
            loans: Vec::new(),
            cleanups: Vec::new(),
            task_scopes: Vec::new(),
            continuation: None,
            select: None,
        });
        assert!(matches!(
            engine.diagnostic_root_value((0, 0, 0)),
            Some(Value::Heap(found)) if found == &handle
        ));
        assert!(engine.diagnostic_root_value((0, 0, 1)).is_none());
        assert!(engine.diagnostic_root_value((0, 0, 2)).is_none());
        assert!(engine.diagnostic_root_value((0, 99, 0)).is_none());

        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine.tasks[1].frames.push(Frame {
            function: BytecodeFunctionId::new(0),
            block: BytecodeBlockId::new(0),
            instruction: 0,
            slots: vec![SlotState::Value(Value::Integer(7))],
            loans: Vec::new(),
            cleanups: Vec::new(),
            task_scopes: Vec::new(),
            continuation: None,
            select: None,
        });
        assert!(matches!(
            engine.diagnostic_root_value((1, 0, 0)),
            Some(Value::Integer(7))
        ));

        let diagnostics = engine.diagnostics.take().unwrap().finish();
        assert!(diagnostics.events.iter().any(|event| matches!(
            event,
            DiagnosticEvent::Resource {
                state: super::super::diagnostics::DiagnosticResourceState::Released,
                ..
            }
        )));
    }

    #[test]
    fn group_operations_preserve_ordered_outcomes_and_affine_drain() {
        let (program, types) = group_program();
        let trace = derive_trace_metadata(&program).unwrap();
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        let error_value = engine
            .allocate(types.string, HeapObject::String("boom".into()), &[])
            .unwrap();
        let ok_value = engine
            .oneshot_result(types.result, Ok(Value::Integer(7)))
            .unwrap();
        let err_value = engine
            .oneshot_result(types.result, Err(error_value.clone()))
            .unwrap();
        assert!(matches!(
            engine.split_group_value(&ok_value, types.string).unwrap(),
            Ok(Value::Integer(7))
        ));
        assert!(matches!(
            engine.split_group_value(&err_value, types.string).unwrap(),
            Err(Value::Heap(_))
        ));
        assert_eq!(
            engine.result_type_id(types.int, types.string).unwrap(),
            types.result
        );
        assert_eq!(
            engine.group_outcome_result(types.all).unwrap(),
            (BytecodeTypeId::new(6), types.string, types.int)
        );
        assert_eq!(
            engine.group_array_element(types.array_result).unwrap(),
            types.result
        );

        let group_value = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(Value::Host(RuntimeValue::Host {
                kind: RuntimeHostValueKind::Group,
                id,
            })) => id,
            _ => panic!("unexpected group value"),
        };
        let completion = engine
            .completion_nominal_value(types.completion, 3, ok_value.clone())
            .unwrap();
        assert!(matches!(completion, Value::Heap(_)));
        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
            TaskCompletion::Returned(ok_value.clone()),
        ))));
        engine.completion_order.insert(1, 1);
        engine
            .groups
            .get_mut(&group_value)
            .unwrap()
            .children
            .push(RuntimeGroupChild {
                task: 1,
                index: 0,
                success: types.int,
                error: types.string,
            });
        let next = engine
            .poll_group_operation(group_value, RuntimeGroupOperation::Next, types.next)
            .unwrap();
        assert!(matches!(next, GroupPoll::Ready(Value::Heap(_))));
        let empty_next = engine
            .poll_group_operation(group_value, RuntimeGroupOperation::Next, types.next)
            .unwrap();
        assert!(matches!(empty_next, GroupPoll::Ready(Value::Heap(_))));
        engine.remove_group(group_value).unwrap();

        let all_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(Value::Host(RuntimeValue::Host { id, .. })) => id,
            _ => panic!("unexpected all group value"),
        };
        for (task, value) in [(2, ok_value.clone()), (3, ok_value.clone())] {
            engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
                TaskCompletion::Returned(value),
            ))));
            engine
                .groups
                .get_mut(&all_group)
                .unwrap()
                .children
                .push(RuntimeGroupChild {
                    task,
                    index: task - 2,
                    success: types.int,
                    error: types.string,
                });
        }
        let all = engine
            .poll_group_operation(all_group, RuntimeGroupOperation::All, types.all)
            .unwrap();
        assert!(matches!(all, GroupPoll::Ready(Value::Heap(_))));

        let settle_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(Value::Host(RuntimeValue::Host { id, .. })) => id,
            _ => panic!("unexpected settle group value"),
        };
        for (task, value) in [(4, ok_value.clone()), (5, err_value.clone())] {
            engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
                TaskCompletion::Returned(value),
            ))));
            engine
                .groups
                .get_mut(&settle_group)
                .unwrap()
                .children
                .push(RuntimeGroupChild {
                    task,
                    index: task - 4,
                    success: types.int,
                    error: types.string,
                });
        }
        let settled = engine
            .poll_group_operation(
                settle_group,
                RuntimeGroupOperation::Settle,
                types.array_result,
            )
            .unwrap();
        assert!(matches!(settled, GroupPoll::Ready(Value::Heap(_))));

        let error_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(Value::Host(RuntimeValue::Host { id, .. })) => id,
            _ => panic!("unexpected error group value"),
        };
        engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
            TaskCompletion::Returned(err_value),
        ))));
        engine
            .groups
            .get_mut(&error_group)
            .unwrap()
            .children
            .push(RuntimeGroupChild {
                task: 6,
                index: 0,
                success: types.int,
                error: types.string,
            });
        let error = engine
            .poll_group_operation(error_group, RuntimeGroupOperation::All, types.all)
            .unwrap();
        assert!(matches!(error, GroupPoll::Ready(Value::Heap(_))));

        let cancel_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(Value::Host(RuntimeValue::Host { id, .. })) => id,
            _ => panic!("unexpected cancel group value"),
        };
        engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
            TaskCompletion::Cancelled,
        ))));
        engine
            .groups
            .get_mut(&cancel_group)
            .unwrap()
            .children
            .push(RuntimeGroupChild {
                task: 7,
                index: 0,
                success: types.int,
                error: types.string,
            });
        let cancelled = engine
            .poll_group_operation(cancel_group, RuntimeGroupOperation::Cancel, types.all)
            .unwrap();
        assert!(matches!(cancelled, GroupPoll::Ready(Value::Unit)));

        let panic_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(Value::Host(RuntimeValue::Host { id, .. })) => id,
            _ => panic!("unexpected panic group value"),
        };
        engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
            TaskCompletion::Panicked(VmPanic {
                code: PanicCode::ExplicitPanic,
                message: "child".into(),
                span: BytecodeSpan {
                    file: 0,
                    start: 0,
                    end: 0,
                },
                stack: Vec::new(),
                suppressed: Vec::new(),
            }),
        ))));
        engine
            .groups
            .get_mut(&panic_group)
            .unwrap()
            .children
            .push(RuntimeGroupChild {
                task: 8,
                index: 0,
                success: types.int,
                error: types.string,
            });
        assert!(matches!(
            engine
                .poll_group_operation(panic_group, RuntimeGroupOperation::All, types.all)
                .unwrap(),
            GroupPoll::Panic(_)
        ));
    }

    #[test]
    fn group_helper_boundaries_are_atomic_and_cancellable() {
        let (mut program, types) = group_program();
        let trace = derive_trace_metadata(&program).unwrap();
        if let BytecodeTypeKind::Intrinsic { arguments, .. } =
            &mut program.types[types.empty_array.index() as usize].kind
        {
            arguments.clear();
        }
        if let BytecodeTypeKind::Nominal { nominal, .. } =
            &mut program.types[types.missing_nominal.index() as usize].kind
        {
            *nominal = Some(BytecodeNominalId::new(99));
        }
        let mut host = RejectingHost;
        let mut engine = Engine::new(
            &program,
            &mut host,
            VmLimits::default(),
            ValueCopyStrategy::default(),
            trace,
        );
        let new_test_group = |engine: &mut Engine| match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        let group_error = engine
            .allocate(types.string, HeapObject::String("group error".into()), &[])
            .unwrap();
        let ok_value = engine
            .oneshot_result(types.result, Ok(Value::Integer(7)))
            .unwrap();
        let err_value = engine
            .oneshot_result(types.result, Err(group_error))
            .unwrap();

        assert!(group_handle(&Value::Integer(1)).is_err());
        assert!(
            group_handle(&Value::Host(RuntimeValue::Host {
                kind: RuntimeHostValueKind::File,
                id: 1,
            }))
            .is_err()
        );
        assert!(
            group_handle(&Value::Host(RuntimeValue::Host {
                kind: RuntimeHostValueKind::Group,
                id: 0,
            }))
            .is_err()
        );
        assert_eq!(
            group_handle(&Value::Host(RuntimeValue::Host {
                kind: RuntimeHostValueKind::Group,
                id: 9,
            }))
            .unwrap(),
            9
        );
        assert!(
            engine
                .join_arguments(BytecodeTypeId::new(u32::MAX))
                .is_err()
        );
        assert!(
            engine
                .validate_group_join(RuntimeJoin {
                    task: usize::MAX,
                    scope: 0,
                })
                .is_err()
        );

        let first_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        let receiver = BytecodeParameter {
            mode: BytecodeParameterMode::Value,
            ty: types.group,
            variadic_element: None,
            receiver: true,
        };
        let callable = |name: &str, outcome: BytecodeTypeId, parameters| BytecodeCallable {
            name: name.into(),
            generic_arity: 0,
            parameters,
            outcome,
            function_type: outcome,
            implementation: None,
            closure: None,
        };
        let unknown = callable("std.async.Group.unknown", types.all, Vec::new());
        assert!(
            engine
                .prepare_group_method(&unknown, &[])
                .unwrap()
                .is_none()
        );
        let no_receiver = callable("std.async.Group.all", types.all, Vec::new());
        assert!(engine.prepare_group_method(&no_receiver, &[]).is_err());
        let missing_receiver = callable("std.async.Group.all", types.all, vec![receiver]);
        assert!(engine.prepare_group_method(&missing_receiver, &[]).is_err());
        assert!(
            engine
                .prepare_group_method(&missing_receiver, &[Value::Integer(1)])
                .is_err()
        );
        let add = callable(
            "std.async.Group.add",
            types.all,
            vec![
                receiver,
                BytecodeParameter {
                    mode: BytecodeParameterMode::Value,
                    ty: types.join,
                    variadic_element: None,
                    receiver: false,
                },
            ],
        );
        let first_handle = Value::Host(RuntimeValue::Host {
            kind: RuntimeHostValueKind::Group,
            id: first_group,
        });
        assert!(
            engine
                .prepare_group_method(&add, std::slice::from_ref(&first_handle))
                .is_err()
        );
        assert!(
            engine
                .prepare_group_method(&add, &[first_handle.clone(), Value::Unit])
                .is_err()
        );

        let dispatch_all_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        let all_callable = callable("std.async.Group.all", types.all, vec![receiver]);
        assert!(matches!(
            engine
                .prepare_group_method(
                    &all_callable,
                    &[Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::Group,
                        id: dispatch_all_group,
                    })],
                )
                .unwrap(),
            Some(OperationResult::Value(_))
        ));
        let dispatch_settle_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        let settle_callable =
            callable("std.async.Group.settle", types.array_result, vec![receiver]);
        assert!(matches!(
            engine
                .prepare_group_method(
                    &settle_callable,
                    &[Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::Group,
                        id: dispatch_settle_group,
                    })],
                )
                .unwrap(),
            Some(OperationResult::Value(_))
        ));
        let dispatch_cancel_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        let cancel_callable = callable("std.async.Group.cancel", types.all, vec![receiver]);
        assert!(matches!(
            engine
                .prepare_group_method(
                    &cancel_callable,
                    &[Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::Group,
                        id: dispatch_cancel_group,
                    })],
                )
                .unwrap(),
            Some(OperationResult::Value(Value::Unit))
        ));
        let dispatch_next_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        let next_callable = callable("std.async.Group.next", types.next, vec![receiver]);
        assert!(matches!(
            engine
                .prepare_group_method(
                    &next_callable,
                    &[Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::Group,
                        id: dispatch_next_group,
                    })],
                )
                .unwrap(),
            Some(OperationResult::GroupWait {
                operation: RuntimeGroupOperation::Next,
                ..
            })
        ));

        engine.next_group_id = u64::MAX;
        assert!(matches!(
            engine.new_group(types.group),
            Err(VmError::ResourceLimit {
                resource: "group handles",
                ..
            })
        ));
        engine.next_group_id = 100;

        assert!(engine.result_type_id(types.string, types.string).is_err());
        assert!(
            engine
                .result_type_id(BytecodeTypeId::new(u32::MAX), types.string)
                .is_err()
        );
        assert!(engine.group_outcome_result(types.result).is_err());
        assert!(
            engine
                .group_outcome_result(BytecodeTypeId::new(u32::MAX))
                .is_err()
        );
        assert!(
            engine
                .group_outcome_result(types.empty_array_result)
                .is_err()
        );
        assert!(engine.group_array_element(types.result).is_err());
        assert!(
            engine
                .group_array_element(BytecodeTypeId::new(u32::MAX))
                .is_err()
        );
        assert!(engine.group_array_element(types.empty_array).is_err());
        assert!(engine.oneshot_result(types.int, Ok(Value::Unit)).is_err());
        assert!(
            engine
                .split_group_value(&Value::Integer(1), types.string)
                .is_err()
        );
        let string_value = engine
            .allocate(types.string, HeapObject::String("not-result".into()), &[])
            .unwrap();
        assert!(
            engine
                .split_group_value(&string_value, types.string)
                .is_err()
        );
        let empty_ok = engine
            .allocate(types.result, HeapObject::ResultOk(None), &[])
            .unwrap();
        assert!(engine.split_group_value(&empty_ok, types.string).is_err());

        assert!(engine.group_is_terminal(first_group).unwrap());
        assert!(engine.group_is_terminal(999).is_err());
        let invalid_child_group = new_test_group(&mut engine);
        engine
            .groups
            .get_mut(&invalid_child_group)
            .unwrap()
            .children
            .push(RuntimeGroupChild {
                task: usize::MAX,
                index: 0,
                success: types.int,
                error: types.string,
            });
        assert!(engine.group_is_terminal(invalid_child_group).is_err());
        engine.remove_group(invalid_child_group).unwrap();
        assert!(engine.remove_group_waiter(999, 0).is_err());
        assert!(engine.remove_group(999).is_err());
        assert!(engine.park_group(999, TaskWait::Scope).is_err());
        assert!(engine.request_group_cancellation(999).is_err());

        let waiting_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine
            .park_group(
                waiting_group,
                TaskWait::GroupTask {
                    id: waiting_group,
                    operation: RuntimeGroupOperation::Next,
                    outcome: types.next,
                    probe: true,
                },
            )
            .unwrap();
        assert!(matches!(engine.tasks[0].status, TaskStatus::Waiting(_)));
        engine.remove_group_waiter(waiting_group, 0).unwrap();
        engine
            .groups
            .get_mut(&waiting_group)
            .unwrap()
            .waiters
            .push(0);
        assert!(engine.remove_group(waiting_group).is_err());

        engine
            .tasks
            .push(scheduler_task(TaskStatus::Waiting(TaskWait::Scope)));
        engine.request_group_child_cancel(1).unwrap();
        assert!(matches!(engine.tasks[1].status, TaskStatus::Runnable));
        assert!(engine.tasks[1].resume.is_some());

        engine.tasks.push(scheduler_task(TaskStatus::Waiting(
            TaskWait::DeferredHostCall {
                call: 1,
                outcome: types.all,
                target: BytecodeBlockId::new(0),
                completion: None,
            },
        )));
        engine.request_group_child_cancel(2).unwrap();
        assert!(engine.tasks[2].cancel_requested);

        engine.tasks.push(scheduler_task(TaskStatus::Running));
        engine.request_group_child_cancel(3).unwrap();
        assert!(engine.tasks[3].cancel_requested);
        engine.tasks.push(scheduler_task(TaskStatus::Complete(Some(
            TaskCompletion::Cancelled,
        ))));
        engine.request_group_child_cancel(4).unwrap();
        assert!(engine.request_group_child_cancel(999).is_err());

        engine.task_scopes.push(Some(RuntimeTaskScope {
            source: BytecodeScopeId::new(0),
            owner: 0,
            children: vec![5],
            closed: false,
        }));
        engine.frames.push(Frame {
            function: BytecodeFunctionId::new(0),
            block: BytecodeBlockId::new(0),
            instruction: 0,
            slots: Vec::new(),
            loans: Vec::new(),
            cleanups: Vec::new(),
            task_scopes: vec![0],
            continuation: None,
            select: None,
        });
        engine.tasks.push(TaskRecord {
            frames: Vec::new(),
            pending_unwind: None,
            async_collect: None,
            status: TaskStatus::Running,
            resume: None,
            queued: false,
            cancel_requested: false,
            waiters: Vec::new(),
            parent_scope: Some(0),
            join_consumed: false,
            panic_observed: false,
            discard_completion: false,
        });
        assert!(
            engine
                .validate_group_join(RuntimeJoin { task: 5, scope: 0 })
                .is_ok()
        );
        engine.tasks[5].join_consumed = true;
        assert!(
            engine
                .validate_group_join(RuntimeJoin { task: 5, scope: 0 })
                .is_err()
        );
        assert_eq!(
            engine.join_arguments(types.join).unwrap(),
            (types.int, types.string)
        );
        assert!(engine.join_arguments(types.int).is_err());

        let add_group = match engine.new_group(types.group).unwrap() {
            OperationResult::Value(value) => group_handle(&value).unwrap(),
            _ => panic!("new_group did not return a handle"),
        };
        engine.task_scopes.push(Some(RuntimeTaskScope {
            source: BytecodeScopeId::new(1),
            owner: 0,
            children: vec![6],
            closed: false,
        }));
        engine.frames.last_mut().unwrap().task_scopes.push(1);
        engine.tasks.push(TaskRecord {
            frames: Vec::new(),
            pending_unwind: None,
            async_collect: None,
            status: TaskStatus::Running,
            resume: None,
            queued: false,
            cancel_requested: false,
            waiters: Vec::new(),
            parent_scope: Some(1),
            join_consumed: false,
            panic_observed: false,
            discard_completion: false,
        });
        let add_group_handle = Value::Host(RuntimeValue::Host {
            kind: RuntimeHostValueKind::Group,
            id: add_group,
        });
        assert!(matches!(
            engine
                .prepare_group_method(
                    &add,
                    &[
                        add_group_handle,
                        Value::Join(RuntimeJoin { task: 6, scope: 1 }),
                    ],
                )
                .unwrap(),
            Some(OperationResult::Value(Value::Unit))
        ));
        assert!(matches!(
            engine
                .poll_group_operation(add_group, RuntimeGroupOperation::All, types.all)
                .unwrap(),
            GroupPoll::Pending
        ));
        engine.request_group_cancellation(add_group).unwrap();
        engine.frames.clear();
        engine.tasks[6].status = TaskStatus::Complete(Some(TaskCompletion::Cancelled));
        assert!(matches!(
            engine
                .poll_group_operation(add_group, RuntimeGroupOperation::All, types.all)
                .unwrap(),
            GroupPoll::Ready(Value::Heap(_))
        ));

        let add_child = |engine: &mut Engine,
                         id: u64,
                         status: TaskStatus,
                         index: usize,
                         sequence: Option<u64>| {
            let task = engine.tasks.len();
            engine.tasks.push(scheduler_task(status));
            if let Some(sequence) = sequence {
                engine.completion_order.insert(task, sequence);
            }
            engine
                .groups
                .get_mut(&id)
                .unwrap()
                .children
                .push(RuntimeGroupChild {
                    task,
                    index,
                    success: types.int,
                    error: types.string,
                });
            task
        };
        let group_panic = |message: &str| {
            TaskCompletion::Panicked(VmPanic {
                code: PanicCode::ExplicitPanic,
                message: message.into(),
                span: BytecodeSpan {
                    file: 0,
                    start: 0,
                    end: 0,
                },
                stack: Vec::new(),
                suppressed: Vec::new(),
            })
        };

        assert!(matches!(
            engine.prepare_group_method(
                &all_callable,
                &[Value::Host(RuntimeValue::Host {
                    kind: RuntimeHostValueKind::Group,
                    id: 999,
                })],
            ),
            Err(VmError::Invariant(message)) if message.contains("unknown group")
        ));
        assert!(matches!(
            engine.split_group_value(&Value::Integer(4), types.never),
            Ok(Ok(Value::Integer(4)))
        ));
        assert!(engine.group_outcome_result(types.array_result).is_err());
        assert!(
            engine
                .completion_nominal_value(types.result, 0, Value::Unit)
                .is_err()
        );
        assert!(
            engine
                .completion_nominal_value(types.malformed_completion, 0, Value::Unit)
                .is_err()
        );
        assert!(
            engine
                .completion_nominal_value(BytecodeTypeId::new(u32::MAX), 0, Value::Unit)
                .is_err()
        );
        assert!(
            engine
                .completion_nominal_value(types.missing_nominal, 0, Value::Unit)
                .is_err()
        );

        let panic_dispatch_group = new_test_group(&mut engine);
        let panic_dispatch_task = add_child(
            &mut engine,
            panic_dispatch_group,
            TaskStatus::Complete(Some(group_panic("prepare"))),
            0,
            None,
        );
        assert!(matches!(
            engine.prepare_group_method(
                &all_callable,
                &[Value::Host(RuntimeValue::Host {
                    kind: RuntimeHostValueKind::Group,
                    id: panic_dispatch_group,
                })],
            ),
            Ok(Some(OperationResult::Panic(PanicCode::ExplicitPanic, message)))
                if message == "prepare"
        ));
        assert!(matches!(
            engine.tasks[panic_dispatch_task].status,
            TaskStatus::Consumed
        ));

        let host_task = engine.tasks.len();
        engine
            .tasks
            .push(scheduler_task(TaskStatus::Waiting(TaskWait::HostCall {
                call: 77,
                outcome: types.all,
                destination: BytecodePlace {
                    slot: BytecodeSlotId::new(0),
                    ty: types.all,
                    projections: Vec::new(),
                    source_loan: None,
                },
                target: BytecodeBlockId::new(0),
                unwind: BytecodeBlockId::new(0),
                completion: None,
            })));
        engine.request_group_child_cancel(host_task).unwrap();
        assert!(engine.tasks[host_task].cancel_requested);

        let missing_order_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            missing_order_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(ok_value.clone()))),
            0,
            None,
        );
        assert!(matches!(
            engine.poll_group_operation(missing_order_group, RuntimeGroupOperation::Next, types.next),
            Err(VmError::Invariant(message)) if message.contains("no order")
        ));
        engine.remove_group(missing_order_group).unwrap();

        let invalid_next_child_group = new_test_group(&mut engine);
        engine
            .groups
            .get_mut(&invalid_next_child_group)
            .unwrap()
            .children
            .push(RuntimeGroupChild {
                task: usize::MAX,
                index: 0,
                success: types.int,
                error: types.string,
            });
        assert!(matches!(
            engine.poll_group_operation(
                invalid_next_child_group,
                RuntimeGroupOperation::Next,
                types.next,
            ),
            Err(VmError::Invariant(message)) if message.contains("invalid task")
        ));
        engine.remove_group(invalid_next_child_group).unwrap();

        let invalid_all_child_group = new_test_group(&mut engine);
        engine
            .groups
            .get_mut(&invalid_all_child_group)
            .unwrap()
            .children
            .push(RuntimeGroupChild {
                task: usize::MAX,
                index: 0,
                success: types.int,
                error: types.string,
            });
        assert!(matches!(
            engine.poll_group_operation(
                invalid_all_child_group,
                RuntimeGroupOperation::All,
                types.all,
            ),
            Err(VmError::Invariant(message)) if message.contains("invalid task")
        ));
        engine.remove_group(invalid_all_child_group).unwrap();

        let invalid_poll_group = new_test_group(&mut engine);
        assert!(matches!(
            engine.poll_group_operation(999, RuntimeGroupOperation::Next, types.next),
            Err(VmError::Invariant(message)) if message.contains("unknown group")
        ));
        engine.remove_group(invalid_poll_group).unwrap();

        let empty_completion_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            empty_completion_group,
            TaskStatus::Complete(None),
            0,
            None,
        );
        assert!(matches!(
            engine.poll_group_operation(empty_completion_group, RuntimeGroupOperation::Next, types.next),
            Err(VmError::Invariant(message)) if message.contains("completion is empty")
        ));
        engine.remove_group(empty_completion_group).unwrap();

        let consumed_group = new_test_group(&mut engine);
        add_child(&mut engine, consumed_group, TaskStatus::Consumed, 0, None);
        assert!(matches!(
            engine
                .poll_group_operation(consumed_group, RuntimeGroupOperation::Next, types.next)
                .unwrap(),
            GroupPoll::Ready(Value::Heap(_))
        ));
        engine.remove_group(consumed_group).unwrap();

        let sequence_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            sequence_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(ok_value.clone()))),
            1,
            Some(10),
        );
        add_child(
            &mut engine,
            sequence_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(ok_value.clone()))),
            0,
            Some(5),
        );
        assert!(matches!(
            engine
                .poll_group_operation(sequence_group, RuntimeGroupOperation::Next, types.next)
                .unwrap(),
            GroupPoll::Ready(Value::Heap(_))
        ));
        assert!(matches!(
            engine
                .poll_group_operation(sequence_group, RuntimeGroupOperation::Next, types.next)
                .unwrap(),
            GroupPoll::Ready(Value::Heap(_))
        ));
        engine.remove_group(sequence_group).unwrap();

        let tie_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            tie_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(ok_value.clone()))),
            1,
            Some(20),
        );
        add_child(
            &mut engine,
            tie_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(ok_value.clone()))),
            0,
            Some(20),
        );
        assert!(matches!(
            engine
                .poll_group_operation(tie_group, RuntimeGroupOperation::Next, types.next)
                .unwrap(),
            GroupPoll::Ready(Value::Heap(_))
        ));
        assert!(matches!(
            engine
                .poll_group_operation(tie_group, RuntimeGroupOperation::Next, types.next)
                .unwrap(),
            GroupPoll::Ready(Value::Heap(_))
        ));
        engine.remove_group(tie_group).unwrap();

        let panic_next_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            panic_next_group,
            TaskStatus::Complete(Some(group_panic("next panic"))),
            0,
            Some(1),
        );
        assert!(matches!(
            engine
                .poll_group_operation(panic_next_group, RuntimeGroupOperation::Next, types.next)
                .unwrap(),
            GroupPoll::Panic(VmPanic { message, .. }) if message == "next panic"
        ));

        let cancelled_next_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            cancelled_next_group,
            TaskStatus::Complete(Some(TaskCompletion::Cancelled)),
            0,
            Some(1),
        );
        assert!(matches!(
            engine
                .poll_group_operation(
                    cancelled_next_group,
                    RuntimeGroupOperation::Next,
                    types.next
                )
                .unwrap(),
            GroupPoll::Ready(Value::Heap(_))
        ));
        engine.remove_group(cancelled_next_group).unwrap();

        let wrong_next_outcome_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            wrong_next_outcome_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(ok_value.clone()))),
            0,
            Some(1),
        );
        assert!(matches!(
            engine.poll_group_operation(
                wrong_next_outcome_group,
                RuntimeGroupOperation::Next,
                types.all,
            ),
            Err(VmError::Invariant(message)) if message.contains("not Option")
        ));
        engine.remove_group(wrong_next_outcome_group).unwrap();

        let empty_all_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            empty_all_group,
            TaskStatus::Complete(None),
            0,
            None,
        );
        assert!(matches!(
            engine.poll_group_operation(empty_all_group, RuntimeGroupOperation::All, types.all),
            Err(VmError::Invariant(message)) if message.contains("completion is empty")
        ));
        engine.remove_group(empty_all_group).unwrap();

        let consumed_all_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            consumed_all_group,
            TaskStatus::Consumed,
            0,
            None,
        );
        assert!(matches!(
            engine.poll_group_operation(consumed_all_group, RuntimeGroupOperation::All, types.all),
            Err(VmError::Invariant(message)) if message.contains("consumed outside")
        ));
        engine.remove_group(consumed_all_group).unwrap();

        let panic_all_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            panic_all_group,
            TaskStatus::Complete(Some(group_panic("first panic"))),
            0,
            None,
        );
        add_child(
            &mut engine,
            panic_all_group,
            TaskStatus::Complete(Some(group_panic("second panic"))),
            1,
            None,
        );
        assert!(matches!(
            engine
                .poll_group_operation(panic_all_group, RuntimeGroupOperation::All, types.all)
                .unwrap(),
            GroupPoll::Panic(VmPanic { suppressed, .. }) if suppressed.len() == 1
        ));

        let infallible_error_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            infallible_error_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(err_value.clone()))),
            0,
            None,
        );
        assert!(matches!(
            engine.poll_group_operation(
                infallible_error_group,
                RuntimeGroupOperation::All,
                types.all_never,
            ),
            Err(VmError::Invariant(message)) if message.contains("infallible outcome")
        ));

        let invalid_settle_group = new_test_group(&mut engine);
        add_child(
            &mut engine,
            invalid_settle_group,
            TaskStatus::Complete(Some(TaskCompletion::Returned(ok_value))),
            0,
            Some(1),
        );
        assert!(matches!(
            engine.poll_group_operation(
                invalid_settle_group,
                RuntimeGroupOperation::Settle,
                types.empty_array,
            ),
            Err(VmError::Invariant(message)) if message.contains("no element type")
        ));
        engine.remove_group(invalid_settle_group).unwrap();

        let invalid_take_group = new_test_group(&mut engine);
        let invalid_child = RuntimeGroupChild {
            task: usize::MAX,
            index: 0,
            success: types.int,
            error: types.string,
        };
        assert!(engine.take_group_completions(&[invalid_child]).is_err());
        engine.remove_group(invalid_take_group).unwrap();

        assert!(matches!(
            engine.spawn_group_task_with_scope(
                999,
                RuntimeGroupOperation::Next,
                types.next,
                None,
                true,
            ),
            Err(VmError::Invariant(message)) if message.contains("unknown group")
        ));
        let cancelled_task = engine.spawn_cancelled_task_with_scope(None).unwrap();
        assert!(matches!(
            engine.tasks[cancelled_task].status,
            TaskStatus::Complete(Some(TaskCompletion::Cancelled))
        ));
    }

    #[test]
    fn executor_helpers_cover_handles_results_and_constructor_boundaries() {
        let (program, types) = executor_program();
        let mut host = RejectingHost;
        let mut engine = executor_engine(&program, &mut host);

        executor_assert!(
            engine
                .executor_handle(&Value::Integer(1), RuntimeHostValueKind::ExecutorPool)
                .is_err()
        );
        executor_assert!(
            engine
                .executor_handle(
                    &Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::ExecutorPool,
                        id: 0,
                    }),
                    RuntimeHostValueKind::ExecutorPool,
                )
                .is_err()
        );
        executor_assert!(
            engine
                .executor_handle(
                    &Value::Host(RuntimeValue::Host {
                        kind: RuntimeHostValueKind::ExecutorActor,
                        id: 1,
                    }),
                    RuntimeHostValueKind::ExecutorPool,
                )
                .is_err()
        );
        let pool_handle = Value::Host(RuntimeValue::Host {
            kind: RuntimeHostValueKind::ExecutorPool,
            id: 1,
        });
        executor_assert_eq!(
            engine
                .executor_handle(&pool_handle, RuntimeHostValueKind::ExecutorPool)
                .unwrap(),
            1
        );

        let function = Value::Function {
            callable: BytecodeCallableId::new(1),
            arguments: Vec::new(),
        };
        executor_assert_eq!(
            engine.executor_callable(&function).unwrap(),
            (BytecodeFunctionId::new(1), Vec::new())
        );
        let captured_string = engine
            .allocate(types.string, HeapObject::String("captured".into()), &[])
            .unwrap();
        let captured_array = engine
            .allocate(
                BytecodeTypeId::new(1),
                HeapObject::Array(vec![Some(captured_string.clone())].into()),
                &[],
            )
            .unwrap();
        let closure = engine
            .allocate(
                BytecodeTypeId::new(16),
                HeapObject::Closure {
                    callable: BytecodeCallableId::new(0),
                    captures: vec![Some(captured_string), Some(captured_array)],
                },
                &[],
            )
            .unwrap();
        executor_assert_eq!(
            engine.executor_callable(&closure).unwrap().0,
            BytecodeFunctionId::new(0)
        );
        executor_assert!(engine.executor_callable(&Value::Integer(1)).is_err());
        executor_assert!(matches!(
            engine.executor_callable(&Value::Function {
                callable: BytecodeCallableId::new(2),
                arguments: Vec::new(),
            }),
            Err(VmError::UnsupportedHostCall(name)) if name == "executor host job"
        ));
        let text = engine
            .allocate(
                types.string,
                HeapObject::String("not a closure".into()),
                &[],
            )
            .unwrap();
        executor_assert!(engine.executor_callable(&text).is_err());

        let ok = engine
            .executor_result_ok(types.pool_result, Value::Integer(4))
            .unwrap();
        executor_assert!(matches!(
            engine.heap.get(ok.heap_handle().unwrap()).unwrap(),
            HeapObject::ResultOk(Some(Value::Integer(4)))
        ));
        executor_assert!(engine.executor_result_ok(types.int, Value::Unit).is_err());
        executor_assert!(matches!(
            engine.executor_error_result(types.job_result, 0),
            Err(VmError::Invariant(message)) if message.contains("not an enum")
        ));
        for variant in 0..4 {
            let error = engine
                .executor_error_result(types.pool_result, variant)
                .unwrap();
            executor_assert_eq!(result_error_variant(&engine, &error), variant as u32);
        }
        executor_assert!(engine.executor_error_result(types.pool_result, 4).is_err());
        executor_assert!(matches!(
            engine.executor_error_result(types.actor_result, 0),
            Err(VmError::Invariant(message)) if message.contains("carries a payload")
        ));
        executor_assert!(matches!(
            engine.executor_actor_error_result(types.job_result, 0, Value::Integer(7)),
            Err(VmError::Invariant(message)) if message.contains("not an enum")
        ));
        executor_assert!(matches!(
            engine.executor_actor_error_result(types.pool_result, 0, Value::Integer(7)),
            Err(VmError::Invariant(message)) if message.contains("no message payload")
        ));
        let actor_error = engine
            .executor_actor_error_result(types.actor_result, 2, Value::Integer(7))
            .unwrap();
        executor_assert!(matches!(
            actor_error,
            Value::Heap(result)
                if matches!(
                    engine.heap.get(result).unwrap(),
                    HeapObject::ResultErr(Some(Value::Heap(error)))
                        if matches!(
                            engine.heap.get(*error).unwrap(),
                            HeapObject::Variant {
                                variant: 2,
                                payload: AggregatePayload::Tuple(values),
                            } if values == &vec![Some(Value::Integer(7))]
                        )
                )
        ));
        executor_assert!(
            engine
                .executor_actor_error_result(types.actor_result, 5, Value::Integer(7))
                .is_err()
        );

        engine.next_executor_id = u64::MAX;
        executor_assert!(matches!(
            engine.next_executor_id(),
            Err(VmError::ResourceLimit {
                resource: "executor handles",
                limit: u64::MAX
            })
        ));
        engine.next_executor_id = 1;

        let pool = executor_metadata("std.executor.pool", types.pool_result, types.function_type);
        executor_assert!(
            engine
                .executor_pool_constructor(&pool, &[Value::Unit, Value::Integer(1)], false)
                .is_err()
        );
        executor_assert_eq!(
            constructor_error_variant(
                &mut engine,
                &pool,
                &[Value::Integer(0), Value::Integer(1)],
                false,
            ),
            0
        );
        executor_assert_eq!(
            constructor_error_variant(
                &mut engine,
                &pool,
                &[Value::Integer(1), Value::Integer(-1)],
                false,
            ),
            1
        );
        executor_assert_eq!(
            constructor_error_variant(
                &mut engine,
                &pool,
                &[Value::Integer(i128::MAX), Value::Integer(1)],
                false,
            ),
            2
        );
        executor_assert_eq!(
            constructor_error_variant(
                &mut engine,
                &pool,
                &[Value::Integer(1), Value::Integer(i128::MAX)],
                false,
            ),
            2
        );
        executor_assert_eq!(
            constructor_error_variant(
                &mut engine,
                &pool,
                &[Value::Integer(4097), Value::Integer(1)],
                false,
            ),
            2
        );
        let blocking = executor_metadata(
            "std.executor.blockingPool",
            types.blocking_result,
            types.function_type,
        );
        let created_blocking = operation_value(
            engine
                .executor_pool_constructor(&blocking, &[Value::Integer(1), Value::Integer(1)], true)
                .unwrap(),
        );
        executor_assert!(matches!(
            engine
                .heap
                .get(created_blocking.heap_handle().unwrap())
                .unwrap(),
            HeapObject::ResultOk(Some(Value::Host(RuntimeValue::Host {
                kind: RuntimeHostValueKind::ExecutorBlockingPool,
                ..
            })))
        ));
        let created = operation_value(
            engine
                .executor_pool_constructor(&pool, &[Value::Integer(1), Value::Integer(0)], false)
                .unwrap(),
        );
        executor_assert!(matches!(
            engine.heap.get(created.heap_handle().unwrap()).unwrap(),
            HeapObject::ResultOk(Some(Value::Host(RuntimeValue::Host {
                kind: RuntimeHostValueKind::ExecutorPool,
                ..
            })))
        ));

        executor_assert!(matches!(
            engine.slice_value(types.string, Value::Integer(1), None, None, None),
            Err(VmError::Invariant(message)) if message.contains("slice base is not managed")
        ));
        let string_value = engine
            .allocate(types.string, HeapObject::String("slice".into()), &[])
            .unwrap();
        executor_assert!(matches!(
            engine.slice_value(
                types.string,
                string_value.clone(),
                Some(Value::Bool(true)),
                None,
                None,
            ),
            Err(VmError::Invariant(message)) if message.contains("slice start is not Int")
        ));
        let sliced = engine
            .slice_value(types.string, string_value, None, None, None)
            .unwrap()
            .unwrap();
        executor_assert!(matches!(
            engine.heap.get(sliced.heap_handle().unwrap()).unwrap(),
            HeapObject::String(value) if value == "slice"
        ));
        let pool_nominal = program
            .nominals
            .iter()
            .enumerate()
            .find_map(|(index, nominal)| {
                (nominal.name == "Pool").then_some(BytecodeNominalId::new(index as u32))
            })
            .unwrap();
        let wrong_slice_shape = engine
            .allocate(
                types.pool,
                HeapObject::Newtype {
                    nominal: pool_nominal,
                    value: Some(Value::Integer(1)),
                },
                &[Value::Integer(1)],
            )
            .unwrap();
        executor_assert!(matches!(
            engine.slice_value(types.string, wrong_slice_shape, None, None, None),
            Err(VmError::Invariant(message)) if message.contains("not Array or String")
        ));
    }

    #[test]
    fn executor_host_defaults_remain_explicit_outside_the_blocking_bridge() {
        let mut host = RejectingHost;
        executor_assert!(matches!(
            host.start_async("executor blocking job", &[]),
            Err(VmError::UnsupportedHostCall(name)) if name == "executor blocking job"
        ));
        executor_assert_eq!(host.poll_async(1).unwrap(), None);
        executor_assert!(matches!(
            host.wait_async(&[]),
            Err(VmError::Invariant(message)) if message.contains("no calls")
        ));
        executor_assert!(host.cancel_async(1).is_ok());
        executor_assert!(host.cleanup(&RuntimeValue::Unit).is_ok());
        executor_assert!(!host.is_virtual_quiescence_call(1));
    }

